Medic.internal.newLifeQuestFixTranslations = {
    ["Stirk Fellowship Soldier^m"] = "soldat de la communauté de Stirk^m",
    ["Stirk Fellowship Mage^f"] = "mage de la communauté de Stirk^f",
    ["Coldharbour Void-Shade^f"] = "ombre du Vide de Havreglace^f",
    ["Statue^m"] = "statue^mf",
    ["Statue^f"] = "statue^f",
    ["Applies to Mages' Fury, Endless Fury, and Mages' Wrath. Select in Skills menu."] = "S'applique à Furie du mage, Furie infinie et Rage de mage. À sélectionner dans le menu des compétences.",
    ["Applies to Dark Exchange, Dark Conversion, and Dark Deal. Select in Skills menu."] = "S'applique à Échange noir, Conversion noire et Pacte noir. À sélectionner dans le menu des compétences.",
    ["Applies to Siphoning Strikes, Leeching Strikes, and Siphoning Attacks. Select in Skills menu."] = "S'applique à Frappes siphonnantes, Attaques sansgue et Attaques siphonnantes. À sélectionner dans le menu des compétences.",
    ["Applies to Strife, Funnel Health, and Swallow Soul. Select in Skills menu."] = "S'applique à Discorde, Captation de vie et Engloutissement de l'âme. À sélectionner dans le menu des compétences.",
    ["Magma Armor, Azure Blue"] = "Armure de magma, bleu glace^f",
    ["Applies to Magma Armor, Corrosive Armor, and Magma Shell. Select in Skills menu."] = "S'applique à Armure de magma, Armure corrosive et Carapace de magma. À sélectionner dans le menu des compétences.",
    ["Molten Weapons, Azure Blue"] = "Armes en fusion, bleu glacier^pf",
    ["Applies to Molten Weapons, Igneous Weapons, and Molten Armaments. Select in Skills menu."] = "S'applique à Armes en fusion, Armes ignées et Armements en fusion. À sélectionner dans le menu des compétences.",
    ["Applies to Arrow Spray, Acid Spray, and Bombard. Select in Skills menu."] = "S'applique à Flèches dispersées, Dispersion acide et Bombarde. Choisir dans le menu Compétences.",
    ["Applies to Twin Slashes, Blood Craze, and Rending Slashes. Select in Skills menu."] = "S'applique à Entailles jumelles, Entailles affaiblissantes et Frénésie sanguinaire. À sélectionner dans le menu des Compétences.",
    ["Dummy Demolisher"] = "Mannequins au tapis",
    ["Crate Topper, Moons Over Orsinium"] = "Bonus de caisse, Lunes sur Orsinium",
    ["Applies to Healing Seed, Budding Seeds, and Corrupting Pollen. Select in Skills menu."] = "S'applique à Graine guérisseuse, Graines bourgeonnantes et Pollen corrupteur. À choisir dans le menu des Compétences.",
    ["Applies to Cleansing Ritual, Extended Ritual, and Ritual of Retribution. Select in Skills menu."] = "S'applique à Rituel d'assainissement, Rituel prolongé et Rituel punitif. À choisir dans le menu des Compétences.",
    ["Applies to Grim Focus, Merciless Resolve, and Relentless Focus. Select in Skills menu."] = "S'applique à Déchaînement meurtrier, Résolution impitoyable et Concentration impitoyable. À choisir dans le menu des Compétences.",
    ["Applies to Frost Cloak, Expansive Frost Cloak, and Ice Fortress. Select in Skills menu."] = "S'applique à Cape de givre, Cape de givre large et Forteresse de glace. À choisir dans le menu des Compétences.",
    ["Applies to Fatecarver, Exhausting Fatecarver, and Pragmatic Fatecarver. Select in Skills menu."] = "S'applique à Sculpte-destin, Sculpte-destin épuisant et Sculpte-destin pragmatique. À sélectionner dans le menu Compétences.",
    ["Applies to Snipe, Focused Aim, and Lethal Arrow. Select in Skills menu."] = "S'applique à Tir de précision, Flèche mortelle et Visée précise. Choisir dans le menu Compétences.",
    ["Applies to Radiant Destruction, Radiant Glory, and Radiant Oppression. Select in Skills menu."] = "S'applique à Destruction radieuse, Gloire radieuse et Oppression radieuse. À choisir dans le menu des Compétences.",
    ["Applies to Puncturing Strikes, Biting Jabs, and Puncturing Sweep. Select in Skills menu."] = "S'applique à Frappes perforantes, Estocs cruels et Balayage perforant. À sélectionner dans le menu Compétences.",
    ["Applies to Bone Armor, Beckoning Armor, and Summoner's Armor. Select in Skills menu."] = "S'applique à Armure d'os, Armure attrayante et Armure d'invocateur. À choisir dans le menu des Compétences.",
    ["Applies to Render Flesh, Blood Sacrifice, and Resistant Flesh. Select in Skills menu."] = "S'applique à Laminage des chairs, Sacrifice de sang et Chair résistante. À choisir dans le menu des Compétences.",
    ["Applies to Abyssal Impact, Cephaliarch's Flail, and Tentacular Dread. Select in Skills menu."] = "S'applique à Impact abyssal, Fléau du céphaliarque et Effroi tentaculaire. À choisir dans le menu des Compétences.",
    ["Applies to Runespite Ward, Impervious Runeward, and Spiteward of the Lucid Mind. Select in Skills menu."] = "S'applique à Camouflet runique, Garde runique implacable et Garde-rancœur de l'esprit lucide. À choisir dans le menu des Compétences.",
    ["Applies to Soul Trap, Consuming Trap, and Soul-Splitting Trap. Select in Skills menu."] = "S'applique à Piège d'âme, Piège de scission d'âme et Piège dévorant. Choisir dans le menu Compétences.",
    ["A small clay statuette in the shape of a bat, painted with red polish.\n\nThe first of three components required to create the Roseblood Bat."] = "Une statuette d'argile à l'effigie d'une chauve-souris, vernie en rouge.\n\nLe premier des trois éléments nécessaires pour créer une chauve-souris rose-de-sang.",
    ["Petals that fall from Sanguine's prized roses are not known to wilt, and are always slightly damp with blood.\n\nThe second of three components required to create the Roseblood Bat."] = "Les pétales qui tombent des roses préférées de Sanghin ne fanent jamais et sont toujours légèrement imprégnés de sang.\n\nLe deuxième des trois composants nécessaires pour créer la chauve-souris rose-de-sang.",
    ["A deadly-sharp rose thorn from one of the myriad rosebushes that grow in Sanguine's eternal paradise. Watch your finger!\n\nThe last of three components required to create the Roseblood Bat."] = "Une épine de rose mortelle, prise sur un des nombreux rosiers qui poussent dans le paradis éternel de Sanghin. Attention aux doigts !\n\nLe dernier des trois composants nécessaires pour créer la chauve-souris rose-de-sang.",
    ["In the halls of the Daedra, their crude mockeries of Tamrielic traditions extend to the courtesies of courtly dancing as well.\n\nA component required for the Roseblood Wings Recall customized action."] = "Dans les salles des Daedra, leurs imitations grossières des traditions de Tamriel vont jusqu'aux arts de la danse.\n\nUn composant nécessaire pour le Rappel aux ailes rose-de-sang.",
    ["Darkly beautiful and ringed with bloody thorns, this fashionable accoutrement lures in dance partners while also pricking those who get too close.\n\nA component required for the Roseblood Wings Recall customized action."] = "D'une beauté sombre et cernée d'épines sanguinolentes, cette touche élégante attire les partenaires de bal... mais pique quiconque s'approche très près.\n\nUn composant nécessaire pour le Rappel aux ailes rose-de-sang.",
    ["Victims of this deadly poison are found with reddened lips; the mark of one last dalliance with forbidden romance.\n\nA component required for the Roseblood Wings Recall customized action."] = "Les victimes de ce poison mortel se reconnaissent à leurs lèvres rouges, la marque d'une dernière tendresse interdite.\n\nUn composant nécessaire pour le Rappel aux ailes rose-de-sang.",
    ["Wardrobe,Costume,Wardrobe,Disguise,Covering,Clothes,Gear,Wear,Worn,Apparel"] = "Garde-robe, Costume, Garde-robe, Déguisement, Couverture, Vêtements, Équipement, Porter, Porté, Tenue,",
    ["Go on with Jeetra. These death-dancers seem to be quite capable! I'm not sure I totally trust the name, though.\n\nAnd don't worry about me. I'll be fine. Just need to clear my head. And … thanks for earlier. Gave me a lot to think about."] = "Accompagnez Jeetra. Ces dansemorts ont l'air redoutables ! Même si ce nom ne m'inspire toujours pas confiance.\n\nEt ne vous inquiétez pas pour moi. Ça ira très bien. Je dois juste m'éclaircir la tête. Et... merci pour tout à l'heure. Ça m'a donné à réfléchir.",
    ["I have to ask—was it fun being a giant statue and stepping on cultists? Because it looked like fun from where I was standing.\n\nAnyway, now that we're here, what's next?"] = "Il faut que je vous demande... c'était amusant d'être une statue géante et de piétiner des adeptes ? Parce que de là où j'étais, ça avait l'air amusant.\n\nBon. Maintenant que nous sommes là, qu'est-ce qu'on fait ?",
    ["What a waste, and all because a lector got greedy. We can rebuild the lodge, but the lives lost … those are gone forever.\n\nStill, it would have been worse if you hadn't shown up. Thanks."] = "Quel gâchis. Tout cela parce qu'une lectrice a laissé la soif de pouvoir l'animer. Nous pourrons reconstruire la loge, mais les vies perdues... elles ont disparu à jamais.\n\nEnfin, cela aurait été pire sans votre arrivée. Merci.",
    ["Latanwen took a fire bolt meant for me. If I can't get her out of here, I'll never forgive myself.\n\nBut who are you, stranger? You don't look like a cultist, and you're certainly not part of the college. What are you doing here?"] = "Latanwën a reçu un éclair de feu qui m'était destiné. Si je ne peux pas la sortir d'ici, je ne me le pardonnerai jamais.\n\nMais qui êtes-vous, <<player{inconnu/inconnue}>> ? Vous n'avez pas une tête d'adepte, et vous n'appartenez pas au collège. Que faites-vous ici ?",
    ["May the Ancient Darkness guide your travels, friend. Perhaps I will see you again some dark night. I jest, I jest. I am a morning person.\n\nFeel free to examine my work. The ancient words of the death-dancers are fascinating!"] = "Puisse les ténèbres anciennes guider vos voyages, mon <<player{ami/amie}>>. Je vous reverrai peut-être au cœur de la nuit. Je plaisante, je plaisante. Je suis plutôt du matin.\n\nN'hésitez pas à examiner mon travail. Les paroles antiques de ces dansemorts sont fascinantes !",
    ["Go get those components for the siege weapon, long-strider.\n\nOr do what Argie says. Suraj isn't your captain. Figure it out yourself! I'm trying to catch some fish. Someone's got to make sure this crew gets fed."] = "Allez chercher les éléments de l'arme de siège, Longue-Foulée.\n\nOu faites ce que vous demande Argenta. Je ne suis pas votre capitaine. Décidez par vous-même ! J'essaie d'attraper du poisson. Il faut bien que quelqu'un nourrisse l'équipage.",
    ["Captain ordered me to stay here and protect the surviving crew.\n\nI would rather be out there doing what you're doing, but orders are orders."] = "Le capitaine m'a ordonné de rester ici pour protéger l'équipage.\n\nJe préférerais être à votre place. Mais les ordres sont les ordres.",
    ["Don't mind Kauldin. Lector Fenworine's betrayal stung him like an angry netch. And after I was wounded and another apprentice fell, he's been extremely cautious.\n\nBut if you aren't with the Worm Cult, who are you?"] = "Ne faites pas attention à Kauldin. La trahison de la lectrice Fenworinë l'a piqué comme un netch enragé. Quand il a vu que j'étais blessée et qu'une autre apprentie était morte, il s'est montré très prudent.\n\nMais si vous n'êtes pas du Culte du Ver, qui êtes-vous ?",
    ["Suraj said he wished we met you before all this. Thinks things would have been different for all of us.\n\nMaybe so. But I've never been one to look back in such a way. Makes my neck hurt."] = "Suraj a dit qu'il aurait aimé vous rencontrer avant tout ça. Il pense que ça aurait changé notre vie.\n\nIl a peut-être raison. Mais je ne suis pas du genre à avoir des regrets. Ça prend trop de place.",
    ["Fine job rousing those mutineers. Desa got here just before you. Quite the spitfire, isn't she? So long as she doesn't eat any of the others, or make a habit of mutiny, she'll make a fine addition to the crew.\n\nWell, are you ready?"] = "Vous avez fait du beau travail en ramenant ces mutins. Desa est arrivée juste avant vous. Elle est impatiente, hein ? Du moment qu'elle ne mange personne, et que ses envies de mutinerie sont assouvies, elle fera une bonne recrue pour l'équipage.\n\nAlors, vous êtes <<player{prêt/prête}>> ?",
    ["Suraj, you've met already. Argenta … requires a bit more patience. Which is why I asked you to speak to her first.\n\nGot no soul, but she's still got a good heart."] = "Suraj, vous le connaissez déjà. Argenta... exige un peu plus de patience. C'est pourquoi je vous demande de lui parler en premier.\n\nElle n'a pas d'âme, mais elle a un bon fond.",
    ["I will aid you if I can, but this fight belongs to you and Darien. The rest of us cannot touch Mannimarco without the Light of Meridia to strengthen our blows."] = "Je vous aiderai si je le peux, mais je crains que Darien et vous ne deviez vous charger de ce combat. Nous ne pourrons pas toucher Mannimarco sans la lumière de Méridia pour renforcer nos coups.",
    ["Those blighting cultists and their Daedra took my sister, Lienyl. We were so close to getting away! She wanted to start a new life outside of Coldharbour.\n\nInstead, we just landed in another nightmare."] = "Ces maudits adeptes et leurs Daedra ont emmené ma sœur, Lienyl. Nous étions à deux doigts de nous enfuir ! Elle voulait commencer une nouvelle vie, en dehors de Havreglace.\n\nAu lieu de cela, nous avons atterri dans un autre cauchemar.",
    ["With all the Daedra, I did not expect to find Tindensea is still here. Perhaps she can help us find the old manuscripts Elder Tso-Nassa spoke of. I would hate to have to search through all these shelves without some guidance."] = "Avec tous ces Daedra, je ne m'attendais pas à ce que Tindensea soit encore là. Elle pourra peut-être nous aider à trouver les anciens manuscrits dont parlait l'ancien Tso-Nassa. Imaginez le cauchemar si nous devions chercher dans ces rayonnages sans personne pour nous guider.",
    ["If you're done talking Darien out of his dark mood, I'm eager to hear your report. Jeetra explained about Vanus's note in the mine, but what happened at the soul flayer harvest sites? Skordo and Raz said you destroyed them, but not much else."] = "Si vous avez fini de remonter le moral de Darien, j'aimerais entendre votre rapport. Jeetra m'a parlé du message de Vanus et de la mine, mais que s'est-il passé aux sites de récolte des flagelleurs ? Skordo et Raz ont dit que vous les avez détruits, mais rien d'autre.",
    ["Captain One-Eye said you mean to give a speech. Didn't have those back at the Caterwaul. Curious what you have to say."] = "Le capitaine Un-Œil a dit que vous vouliez faire un discours. On n'en avait pas sur le Miaulement. Je me demande ce que vous allez dire.",
    ["That's all I have to give to you! At least let me finish the job before I head back to Sunport and turn myself in. I do have a reputation to uphold."] = "Je n'ai rien d'autre à vous donner ! Au moins, laissez-moi remplir mon contrat avant de rentrer à Hélioport pour me livrer à la garde. J'ai une réputation à tenir.",
    ["You get one warning, stranger. I bite. And if you stick around too long, Captain Velehk Sain will take you prisoner and make a meal out of your soul.\n\nNow, get lost before I decide to eat you first."] = "Je ne me répéterai pas, <<player{inconnu/inconnue}>>. Je mords. Et si vous restez trop longtemps dans les parages, le capitaine Velehk Saïn vous capturera et dévorera votre âme.\n\nMaintenant, filez avant que je décide de vous manger en premier.",
    ["That observer is on high alert. Someone must have seen you on your way here and raised the alarm.\n\nI just want to get out. If I'd known Captain Sain treats his crew as well as he treats his prisoners, I'd have just stayed a prisoner."] = "Cet Observateur est en état d'alerte. Quelqu'un a dû vous voir en route et donner l'alarme.\n\nMoi, je veux juste partir. Si j'avais su que le capitaine Saïn traitait son équipage aussi bien qu'il traite ses prisonniers, je serais restée prisonnière.",
    ["Seems like that observer has no idea you're here. You'd lose that advantage if one of us goes with you.\n\nI just want to get out. If I'd known Captain Sain treats his crew as well as he treats his prisoners, I'd have just stayed a prisoner."] = "On dirait que cet Observateur ne se doute pas que vous êtes là. Si un de nous vous accompagne, vous perdrez cet avantage.\n\nMoi, je veux juste partir. Si j'avais su que le capitaine Saïn traitait son équipage aussi bien qu'il traite ses prisonniers, je serais restée prisonnière.",
    ["I am astonished. Ghadaz hasn't performed that well in years. I should start writing letters. People need to see this play."] = "Je suis stupéfaite. Ghadaz n'avait pas aussi bien joué depuis des années. Je dois commencer à écrire des lettres. Il faut que les gens viennent voir cette pièce.",
    ["Let's leave this horrible place of torment and blood so Terinvel and I can calm down. We can talk back at my campsite."] = "Quittons cet horrible endroit de tourment et de sang pour que Tarinvel et moi puissions nous calmer. Nous parlerons à mon campement.",
    ["I was enjoying this batch, but as it says in the Tenets of the Black Worm, there's more victims where those came from.\n\nDark Adept Vairisse's rounds usually take her to the other side of that door about this time. You shouldn't keep her waiting."] = "J'aimais bien ces prisonniers, mais comme on dit dans les Préceptes du Ver noir, il y a toujours d'autres victimes.\n\nLes patrouilles de la sombre adepte Vairisse passent généralement devant notre porte à cet instant précis. Vous ne devriez pas la faire attendre.",
    ["Traveler! Do not attack Sharadak! This one has captured the vile illusionist, Milie Reynaud, after chasing her across land and sea.\n\nShe is a very dangerous prisoner. If Sharadak is not careful, he may fall prey to another one of her vile tricks!"] = "<<player{Voyageur/Voyageuse}>> ! Ne m'attaquez pas ! J'ai capturé l'infâme illusionniste Milie Reynaud après l'avoir poursuivie sur la terre et sur les mers.\n\nC'est une prisonnière très dangereuse. Si je n'y prends garde, je pourrais être victime d'un autre de ses tours !",
    ["Traveler! Sharadak seeks a bounty for the vile illusionist, Milie Reynaud. She is a master of disguise. This one has chased her across land and sea.\n\nIf this one is not careful, he may fall prey to another one of her devious tricks."] = "<<player{Voyageur/Voyageuse}>> ! Je cherche à toucher la prime de l'infâme illusionniste Milie Reynaud. C'est une maîtresse du déguisement. Je la traque sur terre et sur les mers.\n\nSi je n'y prends garde, je pourrais être victime d'un autre de ses tours !",
    ["You're not from in the Hall. I would recognize you. Which means you broke in somehow. Maybe through the rumored breaches in the walls?\n\nDon't fear that I'll hurt you, mortal. I just want to find a way out. I can't survive in this place."] = "Vous ne venez pas des salles. Je vous aurais <<player{reconnu/reconnue}>>. Donc, vous avez réussi à entrer. Peut-être par une brèche dans les murs ?\n\nNe vous inquiétez pas, je ne ferai aucun mal à votre mortelle. Je veux simplement sortir. Je ne survivrai pas, sans cela.",
    ["Of all the times for that silly hound to try to be a hero.\n\nNever realized how much I actually care about him."] = "Cette idiote de chien de mort a bien choisi son jour pour jouer les héroïnes.\n\nJe ne me rendais pas compte comme j'y étais attachée.",
    ["Traveler! You are not with the Worm Cult, are you? I beg a moment of your time. I need someone to deliver a message to Healer Namreras at the Central Siege Camp.\n\nI need you to tell her that her husband, Tesamoril is … dead."] = "<<player{Voyageur/Voyageuse}>> ! Vous n'êtes pas avec le Culte du Ver, n'est-ce pas ? J'aimerais vous accaparer un instant. J'ai besoin de faire porter un message à la guérisseuse Namreras, au camp de siège central.\n\nJ'ai besoin que vous la préveniez de la mort de son mari, Tesamoril.",
    ["Dark Adept Vairisse is a stern commander who does not like to be kept waiting. Which is why we should probably have been faster extracting those souls."] = "La sombre adepte Vairisse est une commandante sévère qui n'aime pas attendre. Nous aurions sans doute dû extraire ces âmes plus vite.",
    ["Is it me or has Skordo gotten worse at holding his liquor?\n\nAnd you! Sit, sit. This has been a long time coming. I've promised you more drinks than I can count. Not sure I can afford to make good on all of them, but let's give it a try!"] = "C'est moi, ou Skordo tient de moins en moins bien l'alcool ?\n\nEt vous ! Asseyez-vous. Ça fait un moment qu'on attend ça. Je vous ai promis plus de verres que je ne pourrais en compter. Je ne sais pas si j'aurai les moyens de tenir toutes mes promesses, mais je peux essayer !",
    ["I must return to the mainland and report all we've uncovered here. Just one more task to add to my already overburdened schedule.\n\nSolstice has been … eventful. I'd welcome a little peace, but peace rarely lingers for those such as us, doesn't it?"] = "Je dois retourner sur le continent et faire mon rapport sur ce que nous avons découvert. Une chose de plus à faire dans un emploi du temps déjà surchargé.\n\nSolstice a été... stimulante. Je me reposerais volontiers, mais les gens comme nous en ont rarement le temps, n'est-ce pas ?",
    ["Oh, thank you so much! I would have been heartbroken if they didn't get something for New Life. Now, allow me to offer you my gratitude. I hope this helps you on your journeys ahead.\n\nReturn soon and we'll make another meal to offer for New Life!"] = "Oh, merci ! J'aurais été dévastée s'ils n'avaient rien eu pour la Nouvelle vie. Permettez que je vous offre ma reconnaissance. J'espère que cela vous sera utile lors de vos voyages.\n\nRevenez me voir bientôt, et nous préparerons un autre repas pour la Nouvelle vie !",
    ["Talk to Lanullin"] = "Parlez à Lanullin",
    ["I prepared the offering and delivered it to the elder."] = "J'ai préparé les offrandes et je les ai livrées aux aînés.",
    ["Then Tibarr proclaims this New Life a success! Allow this one to reward you for your noble efforts. It's the least Tibarr can do for enduring his silly festivity.\n\nAnd Tibarr promises more if you brave his Dragon's lair again!"] = "Alors je proclame que cette Nouvelle vie est un succès ! Permettez que je récompense vos nobles efforts. C'est le moins que je puisse faire, après que vous vous êtes <<player{prêté/prêtée}>> à ces frivolités.\n\nEt je vous en promets davantage si vous revenez défier le dragon !",
    ["Talk to Tibarr"] = "Parlez à Tibarr",
    ["I gave the Dragon's coin to Yarg."] = "J'ai donné la pièce du dragon à Yarg.",
    ["Not bad, traveler. Seeking help is usually a last resort for me, but perhaps I've been too hasty to try to accomplish everything by myself.\n\nThere's still more New Life to celebrate, so feel free to swing by the next time you wander this way."] = "Pas mal, <<player{voyageur/voyageuse}>>. En général, je ne demande de l'aide qu'en tout dernier recours, mais j'ai peut-être eu tort de vouloir tout faire par moi-même.\n\nLa Nouvelle vie n'est pas finie, alors n'hésitez pas à revenir nous voir.",
    ["Talk to Yesei"] = "Parlez à Yesei",
    ["Yes, I cornered your Dakoi, and he gave me this fish for you."] = "Oui, j'ai coincé votre dakoï, et il m'a donné ce poisson pour vous.",
    ["Ah, just like my kin. Take this, along with Mudman's blessing. And you're welcome to return for more.\n\nThe Mudman must thrive through the entire New Life season. And, like all of life, it needs care."] = "Ah, vous êtes comme ma famille. Prenez ceci, et la bénédiction de l'homme de boue. Et n'hésitez pas à revenir.\n\nL'homme de boue doit continuer de prospérer pendant toute la Nouvelle vie. Et comme la vie elle-même, il faut le protéger.",
    ["Talk to Dailonda"] = "Parlez à Dailonda",
    ["You mentioned a reward?"] = "Vous avez mentionné une récompense ?",
    ["Oh, you remember that, do you. Well, what the tusk, it's New Life! You earned the boon and more, and you finally gave me some true competition.\n\nCome back for another swing! Surely there's more Oblivion boulders where that one came from!"] = "Oh, vous n'avez pas oublié. Eh bien, c'est la Nouvelle vie ! Vous avez gagné le bienfait et plus encore. Et vous avez enfin rendu la compétition intéressante.\n\nRevenez jouer du marteau un de ces quatre matins ! Il doit bien y avoir d'autres rochers d'Oblivion quelque part !",
    ["Talk to Mahagog"] = "Parlez à Mahagog",
    ["You mentioned you were going to throw in something extra, I believe."] = "Vous aviez parlé d'un bonus, je crois.",
    ["As long as a piece of the All-Maker resides in Garth, his mood will always hang like a sharp blade over New Life. \n\nI'll continue to do my best to keep him entertained, but should you return I may call upon you again for assistance. Happy New Life!"] = "Tant que Garth aura un morceau de l'Omnifaiseur en lui, son humeur sera toujours une épée suspendue au-dessus de la Nouvelle vie.\n\nJe vais faire de mon mieux pour le divertir, mais si vous revenez, je vous demanderai peut-être un nouveau coup de main. Bonne Nouvelle vie !",
    ["Talk to Baldan"] = "Parlez à Baldan",
    ["You think?"] = "Vous croyez ?",
    ["Indeed. However, centuries of resentment rests beneath these sands. Return if you can to help Yokuda's waters flow here. Another also approaches who may need your help, too.\n\nBefore I take my leave, here. From the Kogo-Hi."] = "Tout à fait. Mais des siècles de ressentiment dorment sous ce sable. Revenez si vous le pouvez, pour faire à nouveau couler l'eau de Yokuda. Et quelqu'un d'autre approche qui pourrait avoir besoin de votre aide.\n\nAvant de partir... tenez, de la part de Kogo-Hi.",
    ["Talk to Hassavir"] = "Parlez à Hassavir",
    ["The ritual is complete then?"] = "Le rituel est accompli ?",
    ["No … but it's like the winds guiding me carried thoughtful eyes, watching my every step. Perhaps it was the heat.\n\nBut I find every ritual helps me understand my own path. And I hope you'll join me again."] = "Non... mais c'est comme si le vent qui me guidait avait contenu des yeux attentifs pour veiller sur mes pas. Ou alors, c'était la chaleur.\n\nMais chaque rituel m'aide à comprendre ma propre voie. Et j'espère que vous m'accompagnerez à nouveau.",
    ["Talk to Jahesi"] = "Parlez à Jahesi",
    ["Did you see someone on your journey?"] = "Avez-vous croisé quelqu'un lors de votre périple ?",
    ["I regret that it has come to this. A fast moving vampiric change means that Terinvel is a danger to everyone. I must deal with it, as a friend should. \n\nI'm grateful for your steady support and calm demeanor through this. Here's payment as promised."] = "Je regrette de devoir en arriver là. Un changement vampirique aussi rapide signifie que Terinvel est un danger pour tout le monde. Je dois l'éliminer. C'est ce que ferait un ami.\n\nMerci de m'avoir soutenue tout au long de cette exploration, et d'avoir gardé votre sang-froid. Voici le paiement promis.",
    ["Why does the dark adept put up with that prince?"] = "Pourquoi la sombre adepte supporte-t-elle ce prince ?",
    ["I do not know which warmth I cherish most. That of the sun's light, the burning coals of our nests, or that of my partner who no longer sleeps beside me. May they rest in stone and memory."] = "Je ne sais pas quelle chaleur je chérissais le plus : celle du soleil, celle des charbons de nos nids ou celle de mon partenaire qui ne dort plus à mon côté. Puisse-t-il reposer dans la pierre et le souvenir.",
    ["First, I'll kill you. Then I'll see the end of Captain One-Eye."] = "D'abord, je vais vous tuer. Puis je m'occuperai du capitaine Un-Œil.",
    ["The Spriggan's going to be ferrying some well-paying passengers off Solstice. I recognize them from back home, but they haven't recognized me yet.\n\nStrange seeing Gahz and Oorbesh be so civil. And I'll be keeping an eye on their … friend."] = "Le Spriggan va transporter quelques passagers plus que généreux. Je les reconnais, j'ai grandi avec elles. Mais elles ne m'ont pas encore reconnu.\n\nC'est étrange de voir Gahz et Oorbesh en si bon termes. Et je vais garder leur ami à l'œil...",
    ["When activated, plays the lively music box composition \"Grave-Stake Gambol.\""] = "Lorsque vous l'activez, joue la composition musicale entraînante « Gigue funéraire ».",
    ["Music Box, Grave-Stake Gambol"] = "boîte à musique, Gigue funéraire^f",
    ["Achievement Furnishings: Solstice"] = "mobilier de succès : Solstice^m",
    ["Solstice Treasure Map VI"] = "Carte au trésor de Solstice VI^f",
    ["Solstice Treasure Map IV"] = "Carte au trésor de Solstice IV^f",
    ["Solstice Treasure Map V"] = "Carte au trésor de Solstice V^f",
    ["This small, well-stitched satchel contains a handful of Trade Bars."] = "Cette petite besace résistante contient une poignée de lingots de commerce.",
    ["Trade Bar Satchel"] = "besace à lingots de commerce^f",
    ["Grants an Outfit Style Collectible. Once used, the Outfit Style is available to all characters on your account. Outfit Styles can be used at an Outfit Station to customize your appearance."] = "Octroie un objet de collection de style de tenues. Une fois utilisé, le style de tenues sera disponible pour tous les personnages de votre compte. Les styles de tenues peuvent être utilisés auprès des ateliers de tenues pour personnaliser votre apparence.",
    ["Bound Style Page: Nokvroz's Greatsword Replica"] = "page de style liée : Réplique d'épée longue de Nokvroz",
    ["Ashbound Hall"] = "Salle cendreliée",
    ["Boss Room"] = "Salle du boss",
    ["Amulet Area"] = "Zone de l'amulette^f",
    ["Dealing damage with a Bash or fully-charged Heavy Attack places the <<1>> on your target for <<2>>. While active, you gain <<3>>, increasing damage done by <<4>>, and deal <<5>> more damage to the target and <<6>> less damage to all other enemies. If the enemy dies while marked, you gain <<7>> Stamina or Magicka, based off your highest maximum resource. This effect can trigger up to every <<8>>."] = "Infliger des dégâts avec un coup de bouclier attaque lourde entièrement chargée place une <<1>> sur votre cible pendant <<2>>. Tant que cette marque demeure, vous gagnez <<3>>, ce qui augmente les dégâts que vous infligez de <<4>>, et vous infligez <<5>> de dégâts en plus à la cible, mais <<6>> de dégâts de moins aux autres ennemis. Si la cible que vous avez marquée meurt, vous gagnez <<7>> Vigueur ou Magie (selon votre ressource la plus élevée). Cet effet ne peut se produire que toutes les <<8>>.",
    ["Quake"] = "Tremblement^m",
    ["Stop"] = "Arrêt^m",
    ["Remove"] = "Suppression^f",
    ["Visability"] = "Visibilité^f",
    ["Mor Naril Priory"] = "Prieuré de Mor Naril",
    ["Note to Gabrielle"] = "Note pour Gabrielle^fd",
    ["Search"] = "Fouiller",
    ["Garth's Feeding Stone"] = "pierre à repas de Garth^fd",
    ["Succulent Honeycomb"] = "miel succulent^m",
    ["Destroy"] = "Détruire",
    ["Mural Dedication"] = "Fresque commémorative",
    ["Writhing Fortress"] = "Forteresse Ondulante^fd",
    ["Currency Vault"] = "Coffre de liquidités",
    ["The currency vault dynamically shows the amount of gold you currently have. As you earn more gold, more shows up inside the vault. As you spend gold, less gold appears inside the vault."] = "Le coffre de liquidités montre de manière dynamique la quantité d'or que vous possédez. Plus vous gagnez d'or, plus vous en verrez dans le coffre. Plus vous dépensez d'or, moi vous en verrez dans ce coffre.",
    ["Bank Safe"] = "Coffre de banque",
    ["Gain access to the bank safe by acquiring 3,000 favor with your pledged faction. Once acquired, you can access your bank and guild bank via this safe."] = "Accédez au coffre de banque en obtenant 3 000 points de faveur auprès de votre faction. Une fois acquis, vous pourrez accéder à votre banque et à votre banque de guilde via ce coffre.",
    ["Faction Banners"] = "Étendards de faction",
    ["Display your allegiance to your faction. After gaining 2,000 favor with your faction, unlock the ability to display their banners in your courtyard."] = "Affichez votre allégeance. Après avoir gagné 2 000 points de faveur auprès de votre faction, vous débloquerez la capacité d'afficher ses couleurs dans votre cour.",
    ["The Worm Cult trapped four Undaunted heroes within soul-forged weapons across Solstice. Free the trapped heroes and learn the truth of their tale in a melancholy tome."] = "Le Culte du Ver a piégé quatre héros Indomptables dans des armes âmeforgées sur Solstice. Libérez les héros et découvrez leur véritable histoire dans un livre bien triste.",
    ["You have life again. Use it and move forward. Without sadness. Without regret."] = "Vous avez à nouveau une vie. Utilisez-la, partez de l'avant. Sans tristesse. Sans regret.",
    ["I smell blood in the water. It's time to fight!"] = "L'eau porte l'odeur du sang ! L'heure est venue de se battre !",
    ["No! Just when Sharadak had her in his clutches, she slips away. Torment! Madness! This one may never recover! … Which way did she go?"] = "Non ! Au moment où je la tenais, elle m'échappe. Tourment ! Folie ! Je ne m'en remettrai jamais... Par où est-elle partie ?",
    ["Well, maybe I'll … I'll just scrap this song."] = "Eh bien, je vais... Je vais peut-être faire une croix sur cette chanson.",
    ["Vanus's dupe and Meridia's fool. Have you come to witness my triumph?"] = "Vanus est un benêt, et Méridia une idiote. Venez-vous assister à mon triomphe ?",
    ["Come on, Jeetra—give me a little credit. I'm just looking. Something's off about this door, I'm trying to figure out what."] = "Allons, Jeetra. Ne me prenez pas pour plus bête que je ne suis. Je regarde, c'est tout. Cette porte est étrange, j'essaie de comprendre pourquoi.",
    ["Destroy the soul flayer, mainlander! It blocks our path!"] = "Détruisez le flagelleur d'âme, <<player{étranger/étrangère}>>. Il nous barre la route.",
    ["When you have the Embellished Dance Card, Rosy Boutonniere, and Sanguine's Goodbye Kiss: \nUse to combine into the Roseblood Wings Recall customized action."] = "Lorsque vous possédez la carte de bal décorée, la rose à la boutonnière et le baiser d'adieu de Sanghin :\nUtilisez pour combiner ces objets et débloquer l'action personnalisée Rappel aux ailes rose-de-sang.",
    ["Today's New Life offering is complete. I should speak to Lanullin and ask about my reward."] = "L'offrande de la Nouvelle vie est terminée pour aujourd'hui. Je devrais parler à Lanullin et lui demander ma récompense.",
    ["I delivered the New Life offering to Lanullin's elder. I should let her know I completed my task."] = "J'ai livré l'offrande de la Nouvelle vie pour le compte de Lanullin. Je devrais la prévenir que les aînés ont reçu leurs plats.",
    ["I need to prepare a banana surprise offering for Lanullin's elder. The grocers and taverns nearby should have a recipe and cooking fire if I need them."] = "Je dois préparer une banane surprise pour un des aînés de Lanullin. Les épiciers et les tavernes des environs devraient avoir une recette et un feu de cuisine si j'en ai besoin.",
    ["I need to prepare a carrot soup offering for Lanullin's elder. The grocers and taverns nearby should have a recipe and cooking fire if I need them."] = "Je dois préparer une soupe de carottes pour un des aînés de Lanullin. Les épiciers et les tavernes des environs devraient avoir une recette et un feu de cuisine si j'en ai besoin.",
    ["I need to prepare a baked potato offering for Lanullin's elder. The grocers and taverns nearby should have a recipe and cooking fire if I need them."] = "Je dois préparer une pomme de terre au four pour un des aînés de Lanullin. Les épiciers et les tavernes des environs devraient avoir une recette et un feu de cuisine si j'en ai besoin.",
    ["Time to deliver the offering. The list Lanullin gave me should say whom to offer this to and where."] = "Il est temps de livrer l'offrande. La liste que Lanullin m'a donnée devrait indiquer ce que je dois livrer à qui.",
    ["Tibarr wants me to steal a coin from the lair of Rawl'kha's Dragon. He mentioned the lair was in a cavern nearby."] = "Tibarr veut que je vole une pièce dans l'antre du dragon de Rawl'kha. Il a indiqué que cet antre était une caverne proche.",
    ["I completed Tibarr's New Life festivity and gave the Dragon's coin to the Orc beggar. Now to claim my own reward from Tibarr."] = "J'ai terminé la festivité de la Nouvelle vie de Tibarr et donné la pièce du dragon au mendiant orque. Je dois aller récupérer ma récompense auprès de Tibarr.",
    ["I swiped the Dragon's coin and donated it to the Orc beggar. Now I should report back to Tibarr."] = "J'ai volé la pièce du dragon pour la donner au mendiant. Je devrais retourner voir Tibarr.",
    ["I swiped the Dragon's coin. Tibarr wants me to give it to the Orc beggar, Yarg. I should talk to him and give him the coin."] = "J'ai escamoté la pièce du dragon. Tibarr veut que je la remette au mendiant, Yarg. Je devrais lui parler et lui donner la pièce.",
    ["Yesei last saw the Dakoi in the streams near Stormhold's outskirts. I should start fishing there."] = "Yesei a vu le dakoï pour la dernière fois dans les cours d'eau près des faubourgs de Fort-tempête. Je devrais commencer à pêcher là-bas.",
    ["I returned to Yesei with fish from the Dakoi. I should speak to him and ask about my reward."] = "Je suis <<player{retourné/retournée}>> voir Yesei avec le poisson du dakoï. Je devrais lui parler et lui demander ma récompense.",
    ["I caught the Dakoi, revealed to be an Argonian acting like a fish. He gave me one to hand to Yesei. I should return to him."] = "J'ai attrapé le dakoï, qui était un Argonien se faisant passer pour un poisson. Il m'en a donné un à remettre à Yesei. Je devrais le lui rapporter.",
    ["Dailonda said she needs fresh mud to spring the Mudman to life. Time to dig."] = "Dailonda a dit qu'elle avait besoin de boue fraîche pour donner vie à l'homme de boue. C'est le moment de creuser.",
    ["I smeared the mud and helped Dailonda complete the Mudman effigy. I should speak to her and ask about my reward."] = "J'ai étalé la boue et j'ai aidé Dailonda à finir son effigie de l'homme de boue. Je devrais lui parler et lui demander ma récompense.",
    ["Mahagog said I could find an Orsimer hammer to use for the challenge at a blacksmith's station in the fortress. I should get it and try to smash the Oblivion boulder."] = "Mahagog m'a dit que je pourrais trouver un marteau orsimer à utiliser pour le défi dans un atelier de forge de la forteresse. Je devrais aller le chercher, puis tenter de briser le rocher d'Oblivion.",
    ["I proved my strength and destroyed the Oblivion boulder. Time to speak to Mahagog about my reward."] = "J'ai prouvé ma force et détruit le rocher d'Oblivion. Il est temps de parler de ma récompense avec Mahagog.",
    ["I need to find some honeycomb to put Garth in a good mood for New Life. The hermit said the forests near Hunter's Glade should have some."] = "Je dois trouver du miel pour mettre Garth de bonne humeur pour la Nouvelle vie. L'ermite a dit que je devrais en trouver dans les forêts près de la Clairière du chasseur.",
    ["I fed Garth the honeycomb and saved all of Tamriel, according to the hermit. I should speak to him and ask about my reward."] = "J'ai donné du miel à Garth et sauvé tout Tamriel, d'après l'ermite. Je devrais lui demander ma récompense.",
    ["I need to fill the waterskin with Yokuda's waters in the west. Once done, I can perform the ritual of Anseilak at Motalion Necropolis."] = "Je dois remplir l'outre avec l'eau de Yokuda, à l'ouest. Une fois que ce sera fait, je pourrai mener l'Anseilak à la nécropole de Motalion.",
    ["I helped Hassavir complete his pilgrimage and performed Anseilak for the fallen Yokudan mages. I should speak to him and ask about my reward."] = "J'ai aidé Hassavir à mener son pèlerinage et à mener l'Anseilak pour les mages yokudans défunts. Je devrais lui parler et lui demander ma récompense.",
    ["Lanullin is preparing her offerings to the elders in Auridon. I should speak to her and learn what I can do to help."] = "Lanullin prépare ses offrandes pour les aînés d'Auridia. Je devrais lui demander ce que je peux faire pour l'aider.",
    ["I should travel to Rawl'kha and find Tibarr to learn more about his New Life festivity."] = "Je devrais aller à Rawl'kha et trouver Tibarr pour en apprendre davantage sur sa festivité de la Nouvelle vie.",
    ["I should look for Yesei in Stormhold and see if he needs help catching the Dakoi fish."] = "Je devrais chercher Yesei à Fort-tempête et voir s'il a besoin d'aide pour attraper le dakoï.",
    ["I should speak to Dailonda in Elden Root to find out more about what she needs help with."] = "Je devrais parler à Dailonda à Faneracine pour en savoir plus sur l'aide dont elle a besoin.",
    ["Mahagog is hosting the festivity with a group of Orcs at Stonetooth Fortress. I should speak to him to learn more about this contest of strength."] = "Mahagog organise les festivités avec un groupe d'Orques à la forteresse de Pierrecroc. Je devrais lui parler pour en savoir plus sur cette épreuve de force.",
    ["The traveler was said to be seen out in Sentinel asking for help. I should start there and speak to them."] = "On m'a parlé d'une personne en pèlerinage qui a besoin d'aide à Sentinelle. Je devrais aller lui parler.",
    ["Anicus mentioned the hermit was spotted in the Rift. I should speak to him and learn more about his pet bear's needs."] = "Anicus a dit qu'on avait aperçu l'ermite dans la Faille. Je devrais lui parler et lui demander de quoi son ours a besoin.",
    ["I helped Jahesi perform Anseilak and gave peace to the fallen Yokudan mages. I should speak to her about my reward."] = "J'ai aidé Jahesi dans son pèlerinage pour amener la paix aux mages yokudans défunts. Je devrais lui parler de ma récompense.",
    ["I need bait to catch the Dakoi fish. Yesei mentioned the Shadowscale camp west from Stormhold might have a bottle of bloodwine that could work."] = "J'ai besoin d'un appât pour attraper le dakoï. Yesei a dit que je trouverai peut-être une bouteille de vin de sang au camp des Écailles d'ombre. Cela devrait faire l'affaire.",
    ["Mahagog mentioned he fought a group of Daedra west of Stonetooth Fortress that left behind an Oblivion boulder for us to smash. I should search the area, find the boulder, and mark its location on my map."] = "Mahagog m'a raconté qu'il avait affronté un groupe de Daedra à l'ouest de la forteresse de Pierrecroc, et qu'ils avaient laissé un rocher d'Oblivion que nous pourrions briser. Je devrais fouiller la zone, trouver le rocher et indiquer son emplacement sur ma carte.",
    ["I found the strange Oblivion boulder. I should return to Mahagog and let him know exactly where it is."] = "J'ai trouvé l'étrange rocher d'Oblivion. Je devrais retourner prévenir Mahagog que je l'ai localisé.",
    ["Mahagog is waiting for me. I should tell him about the boulder I found for our challenge."] = "Mahagog m'attend. Je devrais lui dire que j'ai trouvé le rocher pour notre défi.",
    ["Sirilonwe noticed an abandoned camp to the southeast. She guesses that it might belong to Terinvel and Ormard. I should search it for evidence of where they went."] = "Sirilonwë a remarqué un campement abandonné au sud-est. Elle pense qu'il appartient à Terinvel et Ormard. Je devrais y chercher des traces de leur passage.",
    ["I offered Sirilonwe advice about how to handle Terinvel's transformation into a vampire. It remains to be seen if she takes it. I should talk to her about my reward."] = "J'ai donné à Sirilonwë quelques conseils pour gérer la transformation de Terinvel en vampire. À elle de décider si elle veut les suivre. Je devrais lui parler de ma récompense.",
    ["The abandoned campsite outside Ashbound Hall definitely belonged to Terinvel and Ormard. I found notes from them claiming to know of a side entrance into the Hall. I should talk to Sirilonwe about this."] = "Le campement abandonné près des salles cendreliées appartenaient bel et bien à Terinvel et Ormard. J'ai trouvé des notes indiquant une entrée des salles. Je dois en parler à Sirilonwë.",
    ["Terinvel's dropped note describes a cave entrance that leads inside Ashbound Hall. I should explore to the southwest to find it."] = "La note que Terinvel a perdue décrit une entrée de caverne qui mène dans les salles cendreliées. Je devrais la chercher au sud-ouest.",
    ["I found a crack in the stone that could lead into some caves. This might be the side entrance into Ashbound Hall that Terinvel mentioned in his notes. I should head in and see where it leads me."] = "J'ai trouvé une fissure dans la paroi qui pourrait mener à des cavernes. Il s'agit peut-être de l'entrée des salles cendreliées dont Terinvel parlait dans ses notes. Je devrais suivre ce passage pour voir où il mène.",
    ["A Stirk Fellowship scout named Mihnassi told me about the missing Terinvel and Sirilonwe's need for aid. She said I could find the academic on the road north of Ashbound Hall. I should track her down."] = "Une éclaireuse de la communauté de Stirk appelée Mihnassi m'a <<player{prévenu/prévenue}>> de la disparition de Terinvel, et m'envoie aider Sirilonwë. Elle a dit que l'érudite se trouvait sur la route au nord des salles cendreliées. Je devrais la trouver.",
    ["The crack in the wall led into a cave. I see an opening to a building that may be Ashbound Hall. I should talk to Sirilonwe to discuss our next move."] = "La fissure dans la paroi menait à une caverne. Je vois une ouverture vers un bâtiment, sans doute les salles cendreliées. Je devrais planifier la suite avec Sirilonwë.",
    ["Sirilonwe confirmed that the cave opens into Ashbound Hall. She urged caution as we explore the prison. Vampires lurk everywhere. I should start my search for Terinvel."] = "Sirilonwë m'a confirmé que la grotte donne dans les salles cendreliées. Elle m'a <<player{demandé/demandée}>> de rester <<player{prudent/prudente}>> en explorant la prison. Il y a des vampires partout. Je devrais commencer à chercher Terinvel.",
    ["My search revealed a medallion etched with strange characters. I also found a note describing a method to unlock the sealed door. I need to show these to Sirilonwe."] = "J'ai trouvé un médaillon gravé de caractères étranges. Ainsi qu'une note expliquant comment ouvrir la porte scellée. Je dois montrer tout cela à Sirilonwë.",
    ["Sirilonwe identified the medallion I found as the Aspect of Brutality. It's part of a system that unlocks doors around Ashbound Hall. The note I found describes the Aspect's correct arrangement. I should place this on the unlocking"] = "Sirilonwë a identifié le médaillon que j'ai trouvé comme un Aspect de Brutalité. Il fait partie d'un système qui déverrouille les portes des salles cendreliées. Le message que j'ai trouvé décrit la disposition correcte de l'Aspect. Je devrais le placer sur le mécanisme.",
    ["A young vampire revealed herself to us and claimed she meant no harm. It seems she's the source of the mysterious whispering we heard. I should find out why she's following us."] = "Une jeune vampire s'est présentée à nous, elle assure ne nous vouloir aucun mal. On dirait qu'elle est la source des mystérieux murmures que nous entendions. Je devrais lui demander pourquoi elle nous suit.",
    ["Azartha gave us some helpful information for dealing with Ashbound Hall. Rooms that are more brightly lit than others will keep us safe. Apparently we can find a map in one of those rooms. I should resume my search of the prison."] = "Azatha nous a transmis des renseignements précieux pour traverser les salles cendreliées. Les salles les plus éclairées nous protégeront. Apparemment, je trouverai une carte dans l'une de ces pièces. Je devrais continuer de fouiller la prison.",
    ["We found another room bathed in purple light. Azatha mentioned we might find a map for Ashbound Hall in a room like this. I should search for one."] = "Nous avons trouvé une autre pièce baignée de lumière violette. Azatha a dit que nous pourrions trouver une carte des salles cendreliées dans une salle de ce genre. Je devrais la chercher.",
    ["Our exploration of Ashbound Hall brought us to a magically sealed door. We found a safe room nearby that could provide clues to opening the door. I should look around for anything that stands out."] = "Notre exploration des salles cendreliées nous a conduits à une porte scellée par magie. Nous avons trouvé une chambre proche qui pourrait fournir des indices quant à l'ouverture de la porte. Je finirai bien par remarquer quelque chose.",
    ["During my search for a map of Ashbound Hall, I also found another Aspect medallion. Maybe Sirilonwe can tell me which one it is. I should show it to her along with the map."] = "En cherchant une carte des salles cendreliées, j'ai également trouvé un autre médaillon d'Aspect. Sirilonwë pourra peut-être me dire duquel il s'agit. Je devrais le lui montrer, ainsi que la carte.",
    ["As Sirilonwe and I crossed a bridge, we heard whispering from the shadows. The whispers seem to be talking about us. I should hunt down the source to see if its dangerous."] = "Au moment où Sirilonwë et moi franchissions un pont, nous avons entendu un murmure dans les ombres. La voix semblait parler de nous. Je devrais trouver sa source, et voir si elle est dangereuse.",
    ["With the help of Sirilonwe's spell, I was able to clear the rubble from the bridge. Now I can continue my search of Ashbound Hall for Terinvel."] = "Avec l'aide du sort de Sirilonwë, j'ai pu dégager les débris qui barraient le pont. Je peux continuer de chercher Terinvel dans les salles cendreliées.",
    ["We entered a new section of Ashbound Hall and found another vampire calling out for help. Like Azatha, he claims to be harmless and didn't attack on sight. I should talk to him to see if he can provide information for finding Terinvel."] = "Nous sommes <<player{entrés/entrées}>> dans une nouvelle section des salles cendreliées et avons rencontré un autre vampire qui appelait à l'aide. Comme Azatha, il affirme être inoffensif et n'a pas attaqué à vue. Je devrais lui demander s'il peut nous aider à trouver Terinvel.",
    ["Despite Sirilonwe healing Liviano, he decided to attack us. She turned him into ashes. I should search his remains to see if he did have the Aspect he claimed to."] = "Sirilonwë a soigné Liviano, mais il a tout de même décidé de nous attaquer. Elle l'a réduit en cendres. Je devrais les fouiller pour voir s'il avait l'Aspect dont il parlait.",
    ["Fortunately, I found an Aspect among Livanio's ashes. Lucky for us, Sirilonwe's fire spell didn't melt it. I should check on her to make sure she's all right after this attack."] = "Heureusement, j'ai trouvé un Aspect dans les cendres de Livanio. Par chance, le sort de feu de Sirilonwë ne l'a pas fait fondre. Je devrais m'assurer qu'elle va bien, après cette attaque.",
    ["We unlocked the door by using the Aspects, and entered the next section of Ashbound Hall. Now we can continue our search of this prison for Terinvel."] = "Nous avons déverrouillé la porte avec les Aspects et sommes <<player{entrés/entrées}>> dans la partie suivante des salles cendreliées. Nous pouvons continuer de chercher Terinvel dans cette prison.",
    ["Sirilonwe feels justified in killing Livanio in self-defense. Plus, now we have another important Aspect to help us through this prison. I should follow her into the next section."] = "Sirilonwë estime que la mort de Livanio était un acte de légitime défense. D'autant que nous possédons à présent un autre Aspect pour nous aider à avancer. Je devrais la suivre dans la section suivante.",
    ["The injured Ormard implied that he hid an Aspect somewhere in the central courtyard. I need to look through all this damage until I find it."] = "Blessé, Ormard a laissé entendre qu'il avait caché un Aspect dans la cour centrale. Je dois fouiller les décombres pour le trouver.",
    ["I managed to find an Aspect among the rubble of the central courtyard. Ormard didn't do that good of a job hiding it. I should show it to Sirilonwe."] = "J'ai trouvé un Aspect dans les gravats de la cour centrale. Ormard ne l'avait pas très bien caché. Je devrais le montrer à Sirilonwë.",
    ["The only way out of the central courtyard is through another magically sealed door. I need to place the Aspects in the proper order to unlock the magic."] = "La seule façon de quitter la cour centrale est une autre porte scellée par magie. Je dois placer les Aspects dans le bon ordre pour annuler cette magie.",
    ["We finally caught up with Terinvel. Unfortunately, a powerful vampire named the Elder has captured and bound him. I only see one way to get him free. I should kill the Elder."] = "Nous avons enfin rattrapé Terinvel. Malheureusement, une puissante vampire appelée l'Aînée l'a capturé et lié à son service. Je ne vois qu'une seule façon de le libérer. Je devrais tuer l'Aînée.",
    ["Terinvel is free, even if he doesn't immediately appreciate it. Sirilonwe conjured a portal so that we can leave Ashbound Hall. I should join her outside."] = "Terinvel est libre, même s'il ne l'apprécie pas encore. Sirilonwë a invoqué un portail pour nous permettre de quitter les salles cendreliées. Je devrais la rejoindre dehors.",
    ["I stepped through the portal and arrived outside Ashbound Hall. I can hear Terinvel and Sirilonwe argue with each other. I should check on the newly rescued researcher and see how he feels."] = "J'ai traversé le portail, qui m'a <<player{déposé/déposée}>> devant les salles cendreliées. J'entends Terinvel et Sirilonwë se disputer. Je devrais aller voir comment se sent le chercheur que nous venons de sauver.",
    ["Despite all our efforts, Terinvel didn't escape unscathed. He admits that the Elder passed on vampirism to him. He seems quite excited about the power growing inside him. I should talk to Sirilonwe about this."] = "Malgré tous nos efforts, Terinvel n'est pas sorti de là indemne. Il admet que l'Aînée lui a transmis le vampirisme. Il semble apprécier le pouvoir qui grandit en lui. Je devrais en parler à Sirilonwë.",
    ["After Sirilonwe cast her spell, ghostly versions of Terinvel and Ormard appeared. This was a recreation of a moment in the past. They discussed their plans to go deeper into the Ashbound Halls. I should talk to Sirilonwe about this."] = "Après que Sirilonwë a lancé son sort, des versions fantomatiques de Terinvel et Ormard sont apparues. C'était la reproduction d'un épisode passé. Ils parlaient de leur projet d'exploration des salles cendreliées. Je devrais en discuter avec Sirilonwë.",
    ["With our combined strength, Sirilonwe and I managed to defeat the Elder. Terinvel is now free, if a bit ungrateful. I should wait until he's on his feet to see what we do next."] = "À nous deux, Sirilonwë et moi avons réussi à vaincre l'Aînée. Terinvel est libre, mais il nous en veut. Je devrais attendre qu'il se relève pour décider de la suite.",
    ["When I placed the Aspect of Brutality into the mechanism, the ward disappeared from the door. Sirilonwe and I should continue our search of Ashbound Hall for Terinvel."] = "Lorsque j'ai placé l'Aspect de Brutalité dans le mécanisme, le charme de la porte a disparu. Sirilonwë et moi devrions continuer de chercher Terinvel dans les salles cendreliées.",
    ["Now that we have a rough map of Ashbound Hall, finding Terinvel should be slightly easier. Time to continue forward with our search."] = "Maintenant que nous possédons une carte approximative des salles cendreliées, il sera plus facile de trouver Terinvel. Continuons notre chemin.",
    ["Sirilonwe has a spell that can clear the rubble that blocks our path. Once she starts casting, I need to smash the rubble."] = "Sirilonwë possède un sort qui peut déblayer le chemin. Une fois qu'elle commencera à l'incanter, je dois briser les gravats.",
    ["Sirilonwe and I finally reached the central courtyard and it's in shambles. However, we did manage to find an injured Ormard laying on the ground. He claims to have expected us. I should press him to tell me where Terinvel went."] = "Sirilonwë et moi avons enfin atteint la cour centrale, et elle est en triste état. Mais nous avons trouvé Ormard. Il est blessé et gît au sol. Il dit nous avoir attendus. Je devrais lui demander où Terinvel est parti.",
    ["Sirilowe spotted a camp fire tucked away in a heavily damaged area of the Hall. She thinks it's worth searching. I should look through the camp for any clues."] = "Sirilonwë a repéré un feu de camp, dans une partie très endommagée des salles. Elle pense que nous devrions inspecter les lieux. Je devrais chercher des indices.",
    ["Ashbound Hall's crash landing into Solstice created rubble everywhere. Some of it blocks a bridge we need to cross. I should talk to Sirilonwe about how to clear it."] = "L'atterrissage brutal des salles cendreliées sur Solstice a dispersé des gravats un peu partout. Le pont est impraticable. Je devrais demander à Sirilonwë comment nous pouvons le dégager.",
    ["I found a hat that Sirilonwe claims belong to Ormard. Apparently it spurred an idea in her. I should watch what comes from her spell."] = "J'ai trouvé un chapeau. Sirilonwë affirme qu'il appartenait à Ormard. Apparemment, cela lui a donné une idée. Je devrais regarder ce que donne son sort.",
    ["In the memory that Sirilonwe recreated, Ormard wanted to get to a crater that's just ahead. Now we have a direction for a search. I should find this crater."] = "Dans le souvenir que Sirilonwë a recréé, Ormard voulait atteindre un cratère, un peu plus loin. Nous savons à présent où chercher. Je devrais trouver ce cratère.",
    ["We reached the area of Ashbound Hall that Ormard referred to as a crater. It certainly matches the title. Should continue my search for Terinvel by crossing it."] = "Nous avons atteint la partie des salles cendreliées qu'Ormard appelait le cratère. Le lieu mérite bien son nom. Je devrais le traverser pour continuer de chercher Terinvel.",
    ["We crossed through the crater, but saw no sign of Terinvel or Ormard. Sirilonwe suggested we keep heading in this direction. Perhaps we're hot on their heels. I should continue my search of Ashbound Hall."] = "Nous avons traversé le cratère, mais sans trouver de trace de Terinvel ou d'Ormard. Sirilonwë m'a suggéré de continuer dans la même direction. Nous les rattrapons peut-être. Je devrais continuer de fouiller les salles cendreliées.",
    ["Sirilonwe and I came across another door sealed with magic. Looks like I need to use the Aspects we collected to unlock it. I should find the right placement for the medallions to unlock the door."] = "Sirilonwë et moi avons trouvé une autre porte fermée par magie. On dirait que je dois utiliser les Aspects que nous avons trouvés pour l'ouvrir. Je devrais trouver la bonne disposition.",
    ["I placed all the Aspects in their proper spot and unlocked the door. According to Ormard, Terinvel should be just beyond, but he'll be in the company of someone called the Elder. I should go confront her so we can get out of here."] = "J'ai placé tous les Aspects au bon endroit et j'ai ouvert la porte. D'après Ormard, Terinvel ne devrait plus être très loin, mais il sera avec une certaine Aînée. Je devrais la confronter pour que nous puissions partir au plus vite.",
    ["For Lanullin, celebrating New Life involves giving back to the esteemed elders of her community through good meals. I agreed to help her prepare and deliver them."] = "Pour Lanullin, fêter la Nouvelle vie implique de rendre aux aînés estimables de sa communauté en leur préparant de bons repas. J'ai accepté de l'aider à les préparer et à les livrer.",
    ["Food for New Life"] = "Alimenter la Nouvelle vie",
    ["I met a Khajiit in Rawl'kha who asked me to try and steal coin from a Dragon for his New Life festivity, and then give it to a needy Orc nearby. Apparently, its tricks are challenging to some. I agreed to participate."] = "J'ai rencontré un Khajiit près de Rawl'kha qui m'a demandé de voler une pièce à un dragon pour sa festivité de la Nouvelle vie, puis de la remettre à un Orque dans les parages. Apparemment, ses pièges peuvent être difficiles à éviter. J'ai accepté de participer.",
    ["The Dragon's Hoard"] = "trésor du dragon",
    ["I met an Argonian angler in Stormhold frustrated over not being able to catch the Dakoi, a special fish that's said to appear every New Life festival and bring good fortune. I agreed to hunt and catch the Dakoi for him."] = "J'ai rencontré un pêcheur argonien à Fort-tempête qui s'agace de ne pas pouvoir attraper le dakoï, un poisson spécial qui apparaîtrait à chaque festival de la Nouvelle vie, et qui porte chance. J'ai accepté de chasser et de capturer le dakoï pour lui.",
    ["The Hunt for Dakoi"] = "La chasse au dakoï",
    ["I met a Wood Elf in Grahtwood trying to construct a Mudman effigy for the New Life festival to bless all of Tamriel's green. I agreed to help her gather mud and complete the effigy since her kin aren't there to help."] = "Au bois de Graht, j'ai rencontré une Elfe des Bois qui essayait de construire une effigie de l'homme de boue pour le Festival de la Nouvelle vie, afin de bénir toute la végétation de Tamriel. J'ai accepté de l'aider à rassembler de la boue pour terminer l'effigie, puisque sa famille n'est pas là pour l'aider.",
    ["The Mudman"] = "homme de boue",
    ["I met a group of Orcs in Stonetooth Fortress breaking boulders for Betnikh's Boon during the New Life Festival. Their leader proposed I search an area where he fought Daedra for a stronger boulder to break. I accepted his challenge."] = "J'ai rencontré un groupe d'Orques dans la forteresse de Pierrecroc, qui brisaient des roches pour le bienfait de Betnikh, pendant le Festival de la Nouvelle vie. Leur chef m'a proposé de chercher un gros rocher à briser, dans la zone où il a affronté des Daedra. J'ai accepté son défi.",
    ["Betnihk's Boon"] = "Bienfait de Betnikh",
    ["A member of the Skaal tribe believes the mood of his bear, Garth, during New Life, will determine the fate of Tamriel. He believes honeycomb might make him happy. I agreed to help him."] = "Un membre de la tribu Skaal pense que l'humeur de son ours Garth pendant la Nouvelle vie déterminera le sort de Tamriel. Il est persuadé que du miel pourrait le rendre heureux. J'ai accepté de l'aider.",
    ["The Judgment of Garth"] = "Le Jugement de Garth",
    ["I met a wandering traveler out in Sentinel on pilgrimage to give fallen Yokudan mages Anseilak, a ritual that brings them peace. However, since he's unable to complete the journey, I agreed to help him."] = "J'ai rencontré quelqu'un à Sentinelle, qui menait un pèlerinage pour donner aux mages yokudans l'Anseilak, un rituel qui leur garantira le repos. J'ai accepté de mener ce rituel à sa place.",
    ["The Desert and the Sea"] = "Le Désert et la Mer",
    ["Two academics, Sirilonwe and Terinvel, came to study Ashbound Hall, a vampire prison that arrived with the planemeld on Solstice. However, Terinvel went missing and Sirilonwe needs help finding him among the deadly vampires."] = "Deux érudits, Sirilonwë et Terinvel, sont venus étudier les salles cendreliées, une prison de vampires tombée sur Solstice lors de la Coalescence. Mais Terinvel a disparu, et Sirilonwë a besoin d'aide pour le retrouver parmi ces redoutables vampires.",
    ["Antique Map of Solstice"] = "carte antique de Solstice^f",
    ["A simple stone for a complex task. To connect a family through the ages. Stone is chipped to have many small indentations. Stone-Nest tradition says each face retains some flavor, some memory, of meals past."] = "Une pierre bien simple pour une tâche aussi complexe. Pour lier une famille au travers des âges. La pierre a été entaillée de nombreuses fois. La tradition Nid-de-Pierre veut que chaque face conserve le goût, le souvenir, des repas pris ensemble.",
    ["Five is a number that comes up a lot with Hircine. These fangs represent the Spear of Bitter Mercy, also called Spear with Five Points. They would have been fixed in a warmask belonging to a great chief of the Ket Keptu."] = "Cinq est un nombre récurrent chez Hircine. Ces crocs représentent la Lance de cruelle miséricorde, aussi appelée Lance aux cinq pointes. Ils devaient être fixés à un masque de guerre d'un grand chef des Ket Keptu.",
    ["Ah, of course! The Ket Keptu were hunters and warrior-smiths, a people devoted to the Lord of the Hunt. To carry the Spear of Bitter Mercy was a high honor for their great champions. Whoever wore this warmask was indeed favored by Hircine!"] = "Ah, bien sûr ! Les Ket Keptu étaient des chasseurs et des guerriers artisans. Un peuple entier consacré au Seigneur de la Chasse. Porter la Lance de cruelle miséricorde était un grand honneur pour leurs champions. Quiconque portait ce masque de guerre devait vraiment avoir la faveur d'Hircine !",
    ["I practice conjuration magic."] = "Я владею магией призыва.",
    ["Monthly report from Dark Adept Bruhlz.\n\nRecent Acquisitions:\n\n57 Stone-Nest Argonians taken from villages\n6 Escaped Stone-Nest Argonians, recaptured\n7 Stirk Fellowship soldiers \n1 Argonian necromancer, imprisoned for betraying the order\n\n<scribbled in a different hand>\nThe shackles need more souls to fully merge Coldharbour into this plane. And the improved devices must be tested. For that, we require more prisoners. If you cannot secure them, I will select volunteers from among the faithful in your nest.\n\nAnd make sure the traitor suffers. Sacrifice her last. Let her see what the flayers do to those she felt obligated to protect.\n\nMannimarco, King of Worms"] = "Rapport mensuel du sombre adepte Bruhlz.\n\nAcquisitions récentes :\n\n57 Argoniens Nid-de-Pierre pris dans les villages\n6 Argoniens évadés, recapturés\n7 soldats de la communauté de Stirk\n1 nécromancienne argonienne, emprisonnée pour avoir trahi l'Ordre\n\n<écrit d'une main différente>\nIl faut davantage d'âmes pour que les fers puissent attirer entièrement Havreglace dans ce plan. Et il faut tester les appareils améliorés. Pour cela, il nous faut davantage de prisonniers. Si vous ne pouvez pas les trouver, je choisirai des volontaires parmi les fidèles de votre nid.\n\nEt assurez-vous que la traîtresse souffrira. Sacrifiez-la en dernier. Qu'elle voie ce que les flagelleurs font à ceux qu'elle s'est sentie obligée de protéger.\n\nMannimarco, roi des Vers",
    ["Hail Mannimarco!\n\nYour humble servant reports that our experiments with the new soul flayers have been a resounding success. We disguised ourselves as merchants and brought one of the single-use flayers into a village near the Xul-Haj necropolis. The foolish lizards did not suspect a thing! We retreated to a safe distance to observe and activated the flayer. It performed as expected, sending out a burst of necrotic energy that killed everyone within the prescribed perimeter, sending their souls to the wraithforge. I will now return to collect the flayer for reconditioning.\n\nMay your work on the great rising swell our ranks with unstoppable undead warriors! May we gain an army of the dead from the depths of Xul-Haj!\n\nYour Servant,\nOverseer Bazgrum"] = "Gloire à Mannimarco !\n\nVotre humble serviteur annonce que nos expériences sur les nouveaux flagelleurs d'âme se sont soldées par des succès retentissants. Nous nous sommes déguisés en marchands et avons amené un des flagelleurs à usage unique dans un village près de la nécropole de Xul-Haj. Ces lézards idiots ne se sont doutés de rien ! Une fois à bonne distance pour observer, nous avons activé le flagelleur. Il a rempli sa fonction. L'impulsion nécrotique a tué tous les individus dans le périmètre prévu et envoyé leur âme vers la Forge spectrale. Je vais à présent retourner chercher le flagelleur pour récupérer ses éléments.\n\nPuisse votre œuvre de grande résurrection renforcer nos rangs de guerriers morts-vivants inarrêtables ! Puissions-nous y gagner une armée de morts des profondeurs de Xul Haj !\n\nVotre serviteur,\nSuperviseur Bazgrum",
    ["Investigate the Village of Oozt-Tzel"] = "Enquêtez dans le village d'Oozt-Tzel",
    ["You mentioned the Void. I take it you're here on personal business and want to keep it that way?"] = "Vous avez parlé du Vide. J'imagine que vous venez pour affaires personnelles, et que vous voulez rester discret ?",
    ["No. I'm sorry. I was reassigned to Gristmung Hold when they needed more help with the soul flayer experiments. I do not know where they sent Vanus after that.\n\nBut he wrote a note and slipped it to me. Asked me to get it to Gabrielle when I could."] = "Non. Je regrette. On m'a réaffectée au fort de Gristmung lorsqu'il a fallu plus d'aide pour les essais des flagelleurs d'âme. Je ne sais pas où ils ont envoyé Vanus ensuite.\n\nMais il m'a glissé un message. Pour que je le remette à Gabrielle dès que je pourrais.",
    ["Big, wretched siege weapon. Hits with the very hatred of Coldharbour. Blows against a ship are ruinous, and those against crew are fatal.\n\nNo idea what it would do to Velehk Sain and his lot. But Suraj would love to find out."] = "Une grosse arme de siège. Elle frappe avec toute la haine de Havreglace. Un seul coup suffit à détruire un navire, et à tuer tout l'équipage.\n\nJe ne sais pas ce qu'elle pourrait faire à Velehk Saïn et ses sbires. Mais j'aimerais bien le savoir.",
    ["Sithis worship has been a part of Argonian culture forever, though the Dread Father no longer features prominently in their day-to-day worship. \n\nBut here on Solstice, one warrior in each tribe, the death-dancer, still hews to the old ways."] = "La vénération de Sithis a toujours fait partie de la culture argonienne, même si le Père de la terreur n'est plus très présent dans leurs prières quotidiennes.\n\nMais ici, sur Solstice, un guerrier dans chaque tribu, le dansemort, reste fidèle à ces anciennes traditions.",
    ["Kauldin studied under her. He was one of the apprentices she took under her wing and trained to be a marine.\n\nBut we saw her working with the cultists. She even struck down most of her apprentices. Kauldin's lucky to have survived."] = "Kauldin a été son élève. C'est le seul apprenti qu'elle a pris sous son aile pour en faire un marinier.\n\nMais nous l'avons vue œuvrer avec les adeptes. Elle a même abattu la plupart de ses apprentis. Kauldin a de la chance d'avoir survécu.",
    ["That tracks. We saw her carrying a staff and heading toward the gathering hall at the center of the lodge. When the cultist with her hurled a bolt of fire, I didn't think. I just leaped in front of Consewen.\n\nShe … she would do the same for me."] = "Ce serait raccord. Nous l'avons vue, un bâton en main, se diriger vers la salle commune, au centre de la loge. Lorsque l'adepte qui l'accompagnait a lancé un éclair de feu, j'ai réagi sans réfléchir. Je me suis jetée devant Consewën.\n\nElle... elle aurait fait la même chose pour moi.",
    ["Master Tanertor is alive! That's good to hear!\n\nPlease, activate the portal gate so I can get Latanwen to a healer in Sunport."] = "Maître Tanertor est en vie ! C'est réconfortant !\n\nJe vous en prie, activez le portail pour que je puisse emmener Latanwën voir un guérisseur à Hélioport.",
    ["I do not like to answer such broad questions with a simple yes or no. First off, I am not Meridia. Her powers are not mine to bestow. But power can be transferred from one receptacle to another.\n\nThe Light of Meridia should be no different."] = "Je n'aime pas répondre à une telle question par oui ou par non. D'abord, je ne suis pas Méridia. Ce n'est pas à moi de distribuer ses pouvoirs. Mais on peut transférer du pouvoir d'un réceptacle vers un autre.\n\nCela doit pouvoir se faire avec une lumière de Méridia.",
    ["I thought I heard shrieking. Didn't want to get my hopes up that it might have been her.\n\nPerhaps it's time I let those old bones go. If you're ready to move on, there's another favor I need to ask of you."] = "J'ai cru entendre des cris. Je ne voulais pas m'autoriser à espérer que ce serait elle.\n\nIl est peut-être temps de laisser partir mes vieux os. Si vous êtes <<player{prêt/prête}>> à continuer, j'ai un autre service à vous demander.",
    ["There are two sides to every story. Long after our ancestors first sealed Mor Naril, they had to fight off Corelanya forays. Elven records of those troubled times reside in the library of the Sea and Sword Lodge.\n\nYou could seek your answers there."] = "Chaque histoire possède deux versions. Longtemps après que nos ancêtres avaient isolé Mor Naril, ils ont dû repousser les assauts des Corélanye. Les archives elfiques de cette époque troublée demeurent dans la bibliothèque de la loge de la Mer et des Épées.\n\nVous y trouverez peut-être vos réponses.",
    ["Hmm … very well. Allowing outsiders to have a look at the restricted parts of our collection is rather against the rules, but under these circumstances? I think it would be warranted.\n\nOne moment. I need to refer to our catalog."] = "Hmm. Très bien. Les règles nous interdisent d'ouvrir les collections restreintes aux étrangers, mais vu les circonstances... je pense que cela se justifie.\n\nUn instant. Je dois consulter notre index.",
    ["<These crumbling notes are covered in fading Jel glyphs. In the margins, written in Tamrielic, are translation notes left by a Stone-Shaper some centuries ago.>\n\n<Translation> \"The war is won and yet I continue to toil away. Perhaps the others were right. If one wishes to know the color of obsession, you need only look to my scales. At my aching, calloused claws shaped to the handles of my tools. But I do not work without purpose.\n\n\"I see a new hunger growing in the eyes of our leaders. They see my guardians not as protectors, but as weapons. Tools for a war beyond our shores. This is not why I built them. I will now spend my final years locking them away, along with their control stone. The wonders of this temple, once a testament to our courage, are now a trap for those seeking war in times of peace.\"\n\n* * *\n<Translator's Note> So the vault I glimpsed at the temple's center holds not viridian life, but the forms which were shaped from it. The voskrona. It is strange, translating the words of an Argonian as ancient as I feel. How I empathize with his aches as I see a slow, growing harshness to his glyphs. An unevenness that reveals a petrified shoulder. A locked wrist. Ailments that I too massage between quill strokes.\n\nLife-Carver Tzinik-Muz, we are egg-kin more than I could have realized. I do not seek your guardians as tools of war. In truth, I wished for the secrets of their design so I too could shape life from stone. Hubris is the color of my scales.\n\nI wish I could see these protectors first hand, but this old stone-shaper can proceed no farther into these old ruins. I leave my notes to any egg-kin who may follow in my steps. If you seek out Tzinik-Muz's vault, and the voskrona guardians' control stone, you must first release the three counterweights and face the temple's pendulums with courage.\n\nStone-Shaper Jazeez"] = "<Ces notes froissées sont couvertes de glyphes jel délavés. Dans les marges, en tamriéliques, un sculpte-pierre a ajouté quelques notes de traduction, il y a plusieurs siècles>\n\n<Traduction> « Cette guerre est gagnée, et pourtant, je continue mon ouvrage. Les autres avaient peut-être raison. Si l'on désire connaître la couleur de l'obsession, il suffit de regarder mes écailles. Mes griffes calleuses, déformées par le manche de mes outils. Mais je ne travaille pas sans raison. »\n\n« Je vois une faim nouvelle dans le regard de nos dirigeants. Ils voient mes gardiens non comme des protecteurs, mais comme des armes. Des outils pour une guerre au-delà de nos côtes. Ce n'est pas pour cela que je les ai construits. Je passerai à présent mes dernières années à les enfermer, ainsi que leur pierre de contrôle. Les merveilles de ce temple, testament de notre courage, deviendront un piège pour ceux qui chercheront la guerre en temps de paix. »\n\n* * *\n<Note du traducteur> Alors la chambre forte que j'ai aperçue au centre du temple ne contient pas tant la vie viride que les formes que l'on a façonnées en elle. Les voskrona. C'est étrange, de traduire les paroles d'un Argonien aussi vieux que mon esprit semble l'être. Je comprends ses maux, et la dureté croissante de ses glyphes. Leur irrégularité traduit une épaule pétrifiée. Un poignet bloqué. Autant de souffrances que je masse moi-même entre deux traits de plume.\n\nSculpte-vie Tzinik-Muz, nous sommes plus frères d'œuf que je ne l'aurais cru. Je ne cherche pas vos gardiens comme outils d'une guerre. En vérité, je désirais les secrets de leur création pour créer la vie dans la pierre. L'orgueil est la couleur de mes écailles.\n\nJ'aimerais voir ces protecteurs par moi-même, mais le vieux sculpte-pierre que je suis ne peut aller plus loin dans ces vieilles ruines. Je laisse mes notes pour un frère ou une sœur d'œuf qui suivra mes pas. Si vous cherchez la chambre forte de Tzinik-Muz, et la pierre de contrôle des voskrona, vous devrez activer les trois contrepoids et affronter avec courage les pendules du temple.\n\nSculpte-pierre Jazeez",
    ["I couldn't believe it when I heard that this place had ended up in Nirn. I convinced Sirilonwe that a research trip would provide a lot of information on vampires. Things the Mages Guild can use to combat any who posed a danger. This approach worked as I knew it would.\n\n* * *\nThe trip was uneventful and we made camp. I feel a strange sense of purpose? Energy? I am close. I know it. \nWe met another mage, Ormard. He has worked on a vampire compendium for decades, so it's no surprise that he knew of this place. He's a pleasant Nord fellow and even Sirilonwe warmed to him. \n\nOrmard and I have compared notes. His interest seems purely academic and he is eager to get into the place. Sirilonwe is still making some plans, not wanting to rush headlong into danger as she says. Ormard has been generous with the information he has on the Hall. It has sealed doors, different sections. Ormard says there are unique keys or tokens of some sort to open them. \n\n* * *\nOrmard and I decided to do an initial survey into the Hall. I confessed that my real interest was not so much the vampire denizens, but rather the Daedric artifacts rumored to be held within, and that I wanted to confirm that and maybe even bring one back to do my own research. I said Sirilonwe had strong opinions about what she calls relic hunting so I have not told her my true purpose. Ormard understood. He then confessed he found a break in the foundations! A small cave south of our camp. It will allow us to slip quietly into the place, as the main doors appear to be inaccessible after the place fell out of Coldharbour. \n\nWe're doing it. I am close. My heart is racing. Sirilonwe will be furious, but I am sure I can talk her around."] = "Je n'en suis pas revenu lorsqu'on m'a dit que cet endroit s'était retrouvé sur Nirn. J'ai convaincu Sirilonwë qu'un voyage de recherche nous apporterait de nombreuses informations sur les vampires. Pour aider la guilde des mages à les combattre. Comme je m'en doutais, cela l'a convaincue.\n\n* * *\nLe voyage s'est déroulé sans incident et nous avons dressé le camp. Je ressens une étrange détermination. De l'énergie ? Je suis proche. Je le sens.\nNous avons rencontré un autre mage, Ormard. Il travaille depuis des décennies à un compendium sur les vampires, alors je ne suis pas étonné qu'il ait connu cet endroit. C'est un Nordique charmant, et même Sirilonwë l'apprécie.\n\nOrmard et moi avons comparé nos notes. Son intérêt semble purement académique, et il a hâte de se rendre sur place. Sirilonwë continue d'élaborer des plans, elle ne veut pas se ruer dans le danger. Ormard nous a généreusement fait part de tout ce qu'il sait sur les salles. Ses portes scellées, ses différentes sections. Ormard affirme qu'il existe des clés ou objets uniques pour les ouvrir.\n\n* * *\nOrmard et moi avons décidé de mener un repérage initial des salles. Je lui ai avoué que mon intérêt ne concernait pas tant les vampires qui y résident, mais plutôt les artefacts daedriques qui s'y trouvent. Je voulais confirmer leur présence, et peut-être même en rapporter un pour l'étudier. Mais vu les opinions très tranchées de Sirilonwë sur ce qu'elle appelle la chasse aux reliques, je lui ai caché mes véritables intentions. Ormard a compris. Puis il m'a avoué qu'il avait découvert une brèche dans les fondations ! Une petite caverne au sud de notre camp. Elle nous permettra de nous glisser discrètement dans les lieux, car la grande porte paraît inaccessible depuis la chute hors de Havreglace.\n\nNous y sommes presque. Je touche au but. J'ai le cœur qui bat la chamade. Sirilonwë sera furieuse, mais je saurai l'amadouer.",
    ["The Vos-Toh stone tablets offer a glimpse into Argonian death-dancers' beliefs in ancient times. I find them quite inspiring. They deserve extensive study. There are far more than just these simple words beneath the surface of the carefully carved glyphs.\n\n* * *\nVos-Toh of Song\n\nHail Sithis, the nothing of the Outer Darkness. No gentle truths placate fear. Embrace fear, for it is the song of the blood. We raise our voices to speak the words of the Void, the artistry of the Void, the truth of the Void.\n\n* * *\nVos-Toh of Dance\n\nHail Sithis, the serpent of chaos. Constantly moving. Never still. So we dance a ceaseless promenade. To one day slide and step and bounce joyously into the Void. To enact his will with perfect clarity and one day dance beside the Night Lord himself.\n\n* * *\nVos-Toh of Death\n\nHail Sithis, the ever-changing. What is consumed is restored. This is why we die. To one day soar beyond the reach of sun and stars, to enter the space between. To honor his will. To destroy what was and create what will be."] = "Les tablettes Vos-Toh offrent un aperçu des croyances des dansemorts antiques. Je les trouve tout à fait édifiantes. Elles méritent qu'on les étudie. Et sous la surface, ces glyphes soigneusement tracées contiennent bien plus que ces simples mots.\n\n* * *\nVos-Toh du Chant\n\nVive Sithis, le néant des Ténèbres extérieures. Nulle douce vérité n'apaise la peur. Acceptez la peur, car elle est le chant du sang. Nous élevons la voix pour prononcer les paroles du Vide, la poésie du Vide, la vérité du Vide.\n\n* * *\nVos-Toh de la Danse\n\nVive Sithis, le serpent du chaos. Constamment en mouvement. Jamais au repos. Aussi dansons-nous une promenade incessante. Pour un jour glisser, avancer et bondir joyeusement dans le Vide. Pour appliquer sa volonté avec une clarité parfaite, et un jour danser au côté du Seigneur de la Nuit en personne.\n\n* * *\nVos-Toh de la Mort\n\nVive Sithis, le changeant. Ce qui est consommé est rendu. Voilà pourquoi nous mourons. Pour nous élever un jour hors de vue du soleil et des étoiles, et entrer dans l'espace intermédiaire. Pour honorer sa volonté. Pour détruire ce qui fut, et créer ce qui sera.",
    ["Tell me then, this Mani-Kai. I see a brittle thing, fresh from her egg. Eager as the lichen that grows wide without first placing roots. Do you trust her? Can she really hear the Hist?"] = "Alors dites-moi, cette Mani-Kai. Je vois une petite chose fragile, à peine éclose. Aussi verte que le lichen qui pousse sans planter de racines. Lui faites-vous confiance ? Entend-elle vraiment l'Hist ?",
    ["How lucky are you to have walked through the mud alongside my teacher. You know then that the chimes I carry will help me interpret this tree's song. I only hope it will be enough to prove to these villagers that we are here to help."] = "Quelle chance vous avez d'avoir arpenté la boue avec mon maître. Vous savez donc que ces carillons m'aideront à interpréter le chant de cet arbre. J'espère que cela suffira à prouver aux villageois que nous venons les aider.",
    ["There's a letter over there from Adrolir. It's addressed to you."] = "Il y a une lettre là-bas, signée Adrolir. Elle vous est adressée.",
    ["Need to get more information from Ormard on these doors. Such elaborate mechanisms. Not mechanical. Not wholly magical. He said that he has a way to get past them, thanks to his various partners within the hall. Well, not partners, exactly. He continues to be a bit cagey with his information thus far.\n\nI hope Sirilonwe manages to catch up eventually. She should be here to write down all my observations."] = "Ormard doit m'en dire davantage sur ces portes. Quels mécanismes complexes. Pas tout à fait mécaniques, pas vraiment magiques. Il a dit qu'il possède un moyen de les ouvrir, grâce à ses partenaires dans les salles. Enfin, pas vraiment partenaires. Il continue d'être un peu évasif quand je l'interroge.\n\nJ'espère que Sirilonwë parviendra à me rejoindre. Elle devrait être ici pour noter mes observations.",
    ["If the journals spoke true, their creators intended for them to act as defenders of their people. Let us hope that we have given the egg-kin of Xor-Hist the edge they need to face the necromancers."] = "Si les journaux disent vrai, leur créateur comptait en faire les défenseurs de leur people. Espérons que nous avons donné aux frères d'œuf de Xor-Hist l'avantage dont ils auront besoin contre les nécromanciens.",
    ["Here as in Nirn? A whirlpool opened up on the azure seas. Captain One-Eye cackled and sailed us right in. Somehow she knew it would get us out of Coldharbour.\n\nNo one knew it would drop us from the sky. Or that Velehk Sain would dare to follow."] = "Ici sur Nirn ? Un tourbillon s'est ouvert sur les mers azur. Le capitaine Un-Œil a gloussé et nous a fait filer droit devant. Comme si elle savait que ça nous ferait sortir de Havreglace.\n\nPersonne ne savait qu'on tomberait du ciel. Ni que Velehk Saïn oserait nous suivre.",
    ["by Midconjuror Mirmal of the College of Rituals\n\nFew of Sunport's folk venture across the Solstice Range to visit the eastern half of our fair island. Yet this was not always the case. When House Corelanya first settled on these shores, our ancestors looked beyond the mountains and saw a land ripe for settlement. The fact that the Stone-Nest Argonians already lived there did little to deter the interest of proud kinlords and kinladies who desired a realm wide enough to suit their ambitions.\n\nWhen Kinlord Orlemar came to power in 1E 1017, he decided to act upon those ambitions. During his reign, vast tracts of land in eastern Solstice were parceled out to powerful nobles to settle or exploit as they wished. Yet no one seems to have informed the Stone-Nests about the arrangement. Centuries of strife between Elf and Argonian followed from the haughty kinlord's dealings.\n\nNaturally, Orlemar did not forget himself when handing out parcels of eastern Solstice. The kinlord claimed a magnificent estate in the northern part of the island, and named it Vaedinhill. There he commissioned the building of a great manor-house to serve as his summer palace, a luxurious retreat from the cares of the cares of the throne.\n\nThe cost of building Vaedinhill Manor nearly bankrupted the realm. Constructing such an extravagant palace in the wilds of eastern Solstice, far from the resources and workforce of Sunport, proved expensive indeed. But in 1E 1107, Kinlord Orlemar's palace was finally completed, a vision of fair Summerset amid a virgin wilderness. It was not to last.\n\nArgonian resistance to Kinlord Orlemar's policies was growing. While the kinlord enjoyed his palace for a time, travel to and from Vaedinhill became dangerous. Bands of Stone-Nest warriors began to shadow, and sometimes attack, travelers and wagons on the road to Vaedinhill. Orlemar found it increasingly difficult to maintain his court in the east. He did not visit the manor at all in the last ten years of his life, although he was laid to rest there.\n\nWhen open fighting broke out in 1E 1172, Stone-Nest warriors burned down Vaedinhill. During the troubled years that followed, Orlemar's successors could find neither the funds nor the forces needed to rebuild Vaedinhill. By the time Kinlady Torinwe concluded the Peace of Xor-Hist, House Corelanya had no interest in maintaining grand estates east of the mountains.\n\nOne can still visit the ruins of Vaedinhill to this day. Crumbling walls of white stone and weed-choked courtyards attest to the magnificence of Kinlord Orlemar's vision—and his folly."] = "Par le conjurateur Mirmal du Collège des Rituels\n\nPeu d'habitants d'Hélioport s'aventurent au-delà de la chaîne de Solstice pour visiter la moitié est de notre belle île. Mais il n'en alla pas toujours ainsi. Lorsque la maison Corélanye s'installa sur ces côtes, nos ancêtres se tournèrent vers l'autre côté de ces montagnes et y virent une terre idéale pour la colonisation. Le fait que les Argoniens Nid-de-Pierre y aient déjà vécu ne dissuadait pas les fiers patriarches et matriarches d'y établir leurs ambitions.\n\nLorsque le patriarche Orlemar prit le pouvoir en 1E 1017, il décida de matérialiser ces ambitions. Sous son règne, de vastes étendues de l'est de Solstice furent parcellées et distribuées aux puissants nobles, libres de s'y installer ou de l'exploiter à leur gré. Mais personne ne semble avoir informé les Nid-de-Pierre de cet arrangement. Des siècles de conflits entre les Elfes et les Argoniens suivirent cette décision unilatérale.\n\nNaturellement, Orlemar ne s'oublia pas, à l'heure de distribuer les parcelles de l'est de Solstice. Le patriarche conserva une magnifique propriété dans la partie nord de l'île, et la baptisa Vaedinhill. Il y commanda la construction d'un grand manoir qui lui servirait de palais d'été, une luxueuse retraite loin des soucis du trône.\n\nLe coût de la construction du manoir Vaedinhill faillit mettre le royaume en faillite. L'établissement d'un bâtiment aussi extravagant dans les régions sauvages de l'est de Solstice, loin des ressources et de la main-d'œuvre d'Hélioport, fut plus que ruineux. Mais en 1E 1107, le palais du patriarche Orlemar fut enfin achevé. Une vision du beau Couchant dans une nature sauvage. Cela ne devait pas durer.\n\nLa résistance argonienne aux politiques d'Orlemar allait croissant. Le patriarche profita un temps de son palais, mais la route qui menait à Vaedinhill devint bientôt dangereuse. Des bandes de guerriers Nid-de-Pierre commencèrent à suivre, voire attaquer, les voyageurs et les chariots sur cette route. Orlemar peina de plus en plus à établir sa cour à l'est. Au cours des dix dernières années de sa vie, il ne se rendit pas une seule fois au manoir. Il y fut toutefois inhumé.\n\nLorsque les combats éclatèrent en 1E 1172, les guerriers Nid-de-Pierre brûlèrent Vaedinhill. Pendant les années troublées qui suivirent, les successeurs d'Orlemar ne trouvèrent ni les fonds ni les forces nécessaires à la reconstruction de Vaedinhill. Le temps que la matriarche Torinwë conclue la paix de Xor-Hist, la maison Corélanye n'avait plus aucune envie d'entretenir de grandes propriétés à l'est des montagnes.\n\nOn peut encore visiter les ruines de Vaedinhill de nos jours. Les murs écroulés de pierre banche et les cours envahies de mauvaises herbes attestent de la splendeur de la vision du patriarche Orlemar... et de sa folie.",
    ["Her Kinlady Torinwe of Corelanya, regarding with her favor the native rulers and tribes of Solstice and anxious to put to rest the strife between all the inhabitants of the island, wishes to secure for all impacted by the unrest peace, security, and good will between Elves and Argonians, which has been thus far exacerbated by the aforementioned conflict. \n\nTo this end she, alongside Tuintirrimo of the Corelanyan Guard and Pamaldawe of the Collegium, invite Mahei-Gei, representative for the Tide-Born of the western shores, and Tlekeus, speaking for the Stone-Nest of the eastern reaches, to concur upon the following articles and conditions. \n\nARTICLE THE FIRST\nAs long as all spoken-for inhabitants of Solstice adhere to the articles laid out in this document, they will lay down their arms against one another and vow to refrain from taking any hostile actions regarding ancestral or recent grievances. \n\nARTICLE THE SECOND\nAs set forth by this assembled congregation, the territories belonging to the Corelanya, Stone-Nest, and Tide-Born are hereby recognized as the sovereign land of the peoples thereof. Corelanya and Argonian alike agree not to encroach on the others' lands or impede them from crossing from one territory to another. Henceforth, no permanent dwellings shall be constructed in another's territory without express and written permission.\n\nARTICLE THE THIRD\nIn times when Solstice is threatened, we will temporarily waive the previous articles for the sake of mutual defense. \n\nWe signatories and assembled attendants, having been made fully aware of the provisions of this treaty, accept and enter into the full spirit of the stated agreement. \n\nCompleted at Xor-Hist in the year 1244 of the First Era."] = "La matriarche Torinwë du clan Corélanye, considérant avec faveur les dirigeants et populations indigènes de Solstice, et impatiente de résoudre le conflit entre tous les habitants de l'île, désire assurer à tous ceux qui ont pâti du conflit la paix, la sécurité et la bonne volonté entre les Elfes et les Argoniens, qui furent mises à mal par le conflit susdit.\n\nÀ cette fin, accompagnée de Tuintirrimo de la Garde Corélanye et de Pamaldawë du Collegium, elle invite Mahei-Gei, représentant des Enfants-des-Marées des rives ouest, et Tlekeus, au nom des Nid-de-Pierre de la contrée est, à convenir des articles et conditions suivants.\n\nARTICLE PREMIER\nTant que tous les habitants représentés de Solstice adhéreront aux articles exprimés dans ce document, ils déposeront les armes les uns contre les autres, et jureront de n'entreprendre aucune action hostile concernant leurs griefs ancestraux ou récents.\n\nARTICLE SECOND\nTel que stipulés par la congrégation assemblée, les territoires actuellement aux mains des Corélanye, Nid-de-Pierre et Enfants-des-Marées sont dorénavant reconnus comme souverains. Les Corélanye et les Argoniens acceptent de ne pas empiéter sur leur territoire réciproque, et autorisent aux autres parties la libre circulation sur leurs terres propres. Dorénavant, aucun bâtiment pérenne ne devra être érigé sur le territoire de l'autre sans une permission expresse et écrite.\n\nARTICLE TROISIÈME\nLorsque Solstice sera menacée, nous suspendrons temporairement les articles précédents au nom de la défense mutuelle.\n\nNous, signataires et témoins, ayant reçu présentation des provisions de ce traité, les acceptons et concluons cet accord dans l'esprit entier de ses intentions.\n\nÉtabli à Xor-Hist en l'an 1244 de la Première Ère.",
    ["It's not about falling. It's about getting up once again. And I know you can do that."] = "La question n'est pas de savoir si vous avez failli. La question est de savoir si vous êtes prêt à réessayer. Et je sais que vous pouvez le faire.",
    ["Has anyone ever told you Stone-Nests that your heads are as hard as rocks?"] = "Est-ce que quelqu'un vous a déjà dit que les Nid-de-Pierre avaient la tête dure comme la pierre ?",
    ["Of course. A greataxe. A maul. A greatsword. A spear. A quarterstaff."] = "Bien sûr. Une hache à deux mains. Une masse d'arme. Une épée longue. Une lance. Un bâton.",
    ["\"Release them, vile fiend!\"\n\nThere it is! Such strength. Such power! I feel like I could punch a horse! Has this always been within me? For better or worse, you've helped unleash a beast. Thank you."] = "« Libère-la, infâme créature. »\n\nVoilà. Quelle force. Quelle puissance ! Je pourrais assommer un cheval ! Est-ce que cette force était déjà en moi ? Pour le meilleur ou pour le pire, vous avez libéré un animal. Merci.",
    ["Return to Lanullin"] = "Retournez voir Lanullin",
    ["Deliver Baked Potato to Nenilon"] = "Livrez la pomme de terre au four à Nenilon",
    ["So you readily admit you were manipulated? How easily a little stone bends to the whims of wind and rain. You've wasted enough of my time. As the village's death-dancer, it is my duty to strike you down. Ready yourself."] = "Alors vous admettez qu'elle vous a <<player{manipulé/manipulée}>> ? Comme une petite pierre se plie facilement aux caprices du vent et de la pluie. Vous m'avez fait perdre assez de temps. En tant que dansemort du village, il est de mon devoir de vous abattre. Préparez-vous.",
    ["Deliver Banana Surprise to Geraldrim"] = "Livrez la banane surprise à Geraldrim",
    ["Deliver Carrot Soup to Teliwe"] = "Livrez la soupe de carottes à Teliwë",
    ["Craft Banana Surprise"] = "Préparez une banane surprise",
    ["Craft Carrot Soup"] = "Préparer de la soupe de carottes",
    ["Craft Baked Potato"] = "Préparez une pomme de terre au four",
    ["You need to gain Prince Naemon's trust, too. I would do it myself, but he knows me too well. \n\nHis chambers are through the door to our left. Now that I'm in the citadel, I can help with whatever task he gives you. So find me when you're done."] = "Vous devez aussi gagner la confiance du prince. Je le ferais volontiers moi-même, mais il ne me connaît que trop bien.\n\nSes appartements sont derrière la porte sur notre gauche. Maintenant que je suis dans la citadelle, je pourrai vous aider s'il vous confie des missions. Alors venez me voir lorsque vous en aurez fini.",
    ["And how funny is it that the roots of their Hist tree forced them to abandon this temple. There is poetry to that, I am certain of it, but I have not an artist's patience."] = "Et il est amusant que les racines de leur Hist les aient forcés à abandonner ce temple. C'est presque poétique, j'en suis sûre, mais je n'ai pas la patience d'une artiste.",
    ["You must be Sirilonwe. The scout Mihnassi told me you lost your friend near the Ashbound Hall."] = "Vous devez être Sirilonwë. L'éclaireuse Mihnassi m'a dit que vous avez perdu votre ami près des salles cendreliées.",
    ["Soon after the Wall fell, a mage named Ormard came to us. He'd seen the Hall and offered to guide us here. Now I wake up and they're both gone. Come, I'll pay you to escort me while I find Terinvel. The vampires may no longer be securely locked away."] = "Peu après la chute du Mur, un mage appelé Ormard nous a contactés. Il avait vu les salles et proposait de nous y mener. Maintenant, je me réveille et ils ont tous les deux disparu. Venez, je vous paierai si vous m'escortez jusqu'à ce que je retrouve Terinvel. Les vampires ne sont peut-être plus enfermés.",
    ["As I understand it, the Stone-Nest Argonians had numerous encounters with the Daedra when they first arrived on the island. After capturing and guarding the relic for generations, they gave it to us to protect. We must retrieve it."] = "D'après ce que j'ai compris, les Argoniens Nid-de-Pierre ont connu de nombreux affrontements contre les Daedra en arrivant sur l'île. Après avoir capturé et protégé cette relique pendant des générations, ils nous l'ont confiée. Nous devons la récupérer.",
    ["Return to Tibarr"] = "Retournez voir Tibarr",
    ["Give the Coin to the Beggar"] = "Donnez la pièce au mendiant",
    ["Steal a Coin from the Dragon's Hoard"] = "Volez une pièce dans le trésor du dragon",
    ["For now, I'll rest. But it's likely Fenworine reported to some bigger Worm Cult nest. My plan is to meet Master Tanertor with an idea I had to bury them for good.\n\nAnd I'll do it with or without his help."] = "Pour l'heure, je vais me reposer. Mais Fenworinë a dû faire son rapport à un nid du Culte du Ver plus conséquent. Je compte présenter une idée à maître Tanertor pour les enterrer une fois pour toutes.\n\nEt je le ferai, avec ou sans son aide.",
    ["Tell me more about Velehk Sain."] = "Parlez-moi de Velehk Saïn.",
    ["Well, we're a long way from Alten Corimont, aren't we, pirate?\n\nAh, seems so long ago. Can't even remember the sounds and smells of the swamp. Sight's still burning with those endless waves of azure plasm. But it's good to be back in my home plane."] = "Eh bien, nous sommes bien loin d'Alten Corimont, pas vrai pirate ?\n\nÇa remonte à si longtemps. Je ne me souviens même plus à quoi ce marais ressemblait. J'ai encore les yeux éblouis par ces vagues infinies de plasme azur. Mais ça fait du bien de rentrer dans mon plan natal.",
    ["Hunt Down the Dakoi"] = "Chassez le dakoï",
    ["There was. Celbrim. We were all with Master Rolmedil when the attack happened. He went to go help others after the portal didn't open. I chose to stay and protect Rolmedil, but ….\n\nI was just as scared, too."] = "Oui. Celbrim. Nous étions tous avec maître Rolmedil au moment de l'attaque. Il est parti aider les autres quand le portail ne s'est pas ouvert. J'ai préféré rester pour protéger Rolmedil, mais...\n\nJ'ai eu peur, aussi.",
    ["You had no qualms about ending me. Prove to me that you can be just as ruthless toward this spy as you were toward me. Take the Eye to the room upstairs. No need to make a mess here.\n\nBring me proof when she's dead."] = "Vous n'auriez pas hésité à me tuer. Prouvez-moi que vous pouvez être aussi impitoyable envers cette espionne. Conduisez l'Œil dans la pièce à l'étage. Pas la peine de salir cet endroit.\n\nApportez-moi la preuve de sa mort.",
    ["Thank you. I'm certain he would rather fling himself into the forge than open up to one of us. I'll try and mend things with Alma. We should've listened to her like you did."] = "Merci. Je suis certaine qu'il préférerait se jeter dans la forge que de nous parler de ses sentiments. Je vais essayer d'arranger les choses avec Alma. Nous aurions dû l'écouter, comme vous l'avez fait.",
    ["Track the Dakoi"] = "Traquez le dakoï",
    ["Confront the Dakoi"] = "Faites face au dakoï",
    ["Return to Yesei"] = "Retournez voir Yesei",
    ["Assist in Sculpting the Mudman"] = "Aidez à sculpter l'homme de boue",
    ["Gather Mud"] = "Rassembler de la boue",
    ["Return to Dailonda"] = "Retournez voir Dailonda",
    ["Smear Mud on the Mudman"] = "Étalez de la boue sur l'homme de boue",
    ["Prove Your Strength"] = "Prouvez votre force",
    ["Take Hammer"] = "Prendre le marteau",
    ["Return to Mahagog"] = "Retournez voir Mahagog",
    ["Break the Boulder"] = "Brisez le rocher",
    ["Gather Honeycomb for Garth"] = "Trouvez du miel pour Garth",
    ["Gather Honeycomb"] = "Trouvez du miel",
    ["Return to Garth"] = "Retournez auprès de Garth",
    ["Place the Honeycomb on the Feeding Stone"] = "Placez le miel sur la pierre à repas",
    ["Perform the Ritual of Anseilak"] = "Accomplissez le rituel d'Anseilak",
    ["Gather Seawater"] = "Récupérez de l'eau de mer",
    ["Travel to Motalion Necropolis"] = "Allez à la nécropole de Motalion",
    ["Complete the Ritual of Anseilak"] = "Accomplissez le rituel d'Anseilak",
    ["You didn't know. I suspect the Dark Elf was clueless, too. Ormard was a vampire imprisoned here. Before we fell, that is.\n\nBlind wandering won't help save the mortal. Go south, look for other brightly lit rooms. You'll find a map on the wall in one."] = "Vous ne saviez pas. J'imagine que l'Elfe noir ne se doutait de rien. Ormard était un vampire emprisonné ici. Avant notre chute.\n\nVous ne sauverez pas le mortel en avançant à l'aveuglette. Allez au sud, cherchez d'autres salles vivement éclairées. Vous trouverez une carte sur un des murs.",
    ["We can hope. Though my suspicions grow the deeper we get inside this prison. Who left these Aspects around for us to easily find? And why was Terinvel so eager to rush in without me?\n\nAnd finally, why am I friends with such an inconsiderate person?"] = "Nous pouvons l'espérer. Mais mes soupçons ne font que s'aggraver. Qui a placé ces Aspects pour que nous les trouvions aussi facilement ? Et pourquoi Terinvel était-il si pressé d'entrer sans moi ?\n\nEt enfin, pourquoi suis-je amie avec une personne aussi égoïste ?",
    ["I'll answer any questions, if you spare a potion or spell to aid me. \n\nYes, Ormard and a Dark Elf came through here. They did not notice me. They left in the direction of the courtyard."] = "J'accepte de répondre à vos questions si vous avez une potion ou un sort pour m'aider.\n\nOui, Ormard et un Elfe noir sont passés par ici. Ils ne m'ont pas remarqué. Ils partaient en direction de la cour.",
    ["Thank you, stranger. I just want to leave this place. \n\nI had a family once, outside. I want to tell them what happened to me, if they're still alive."] = "Merci, <<player{inconnu/inconnue}>>. Tout ce que je veux, c'est partir d'ici.\n\nJ'avais de la famille, autrefois, à l'extérieur. Je veux leur dire ce qui m'est arrivé, s'ils sont encore en vie.",
    ["Talk to the Lone Traveler"] = "Parlez à la personne en pèlerinage",
    ["Fair warning—take even a sip and this partnership ends here and now. Bloodmite doesn't drink my blood, but he can find me just by taking a whiff of it. \n\nStrangely, it even helps relax him when he gets anxious."] = "Je vous préviens... si vous buvez ne serait-ce qu'une goutte, notre partenariat s'achève immédiatement. Mite-vampire ne boit pas mon sang, mais elle pourra me retrouver à l'odeur.\n\nÉtrangement, ça l'aide même à se détendre quand elle est nerveuse.",
    ["Talk to the Hermit"] = "Parlez à l'ermite",
    ["I don't know. Such new feelings. Urges to dominate. Perhaps I'll take control of the University. Make all those pitiful academics praise me.\n\nYou should talk to Sirilonwe. I feel powerful thirst coming on."] = "Je ne sais pas. Ce sentiment est si nouveau. Je vais peut-être prendre le contrôle de l'université. Pour que tous ces pathétiques académiciens me vénèrent.\n\nVous devriez parler à Sirilonwë. Je sens que la soif monte.",
    ["Heh. Been around my crew so long I forgot it might unsettle folk.\n\nIt's a curse. One I took to save the souls of the Lost Fleet, press-ganged past death to serve in Coldharbour. Now, it's just who I am. No thought of changing back."] = "Ha. Je suis avec mon équipage depuis si longtemps que j'oublie combien ça peut être surprenant.\n\nC'est une malédiction. Je l'ai acceptée pour sauver l'âme des marins de la Flotte perdue, forcés de servir en Havreglace. Maintenant, je suis comme ça. Aucune chance de revenir en arrière.",
    ["Dosu and I disagree on everything. Always have. But recently, we found something we agree on. Our feelings for one another.\n\nBut in how to consecrate this bond, we clearly disagree. Which courting custom would you find more meaningful, mainlander?"] = "Dosu et moi ne sommes d'accord sur rien. C'est comme ça depuis toujours. Mais récemment, nous nous sommes mis d'accord sur un point. Nos sentiments l'un pour l'autre.\n\nMais nous différons sur la manière de consacrer ce lien. Quelle coutume nuptiale a le plus de sens à vos yeux, <<player{étranger/étrangère}>> ?",
    ["Well, yes … it all happened so fast! With her dying breath, brave Golvyni threw herself back into the fray to save me. I … I am not worthy of such a noble deed … but I shall try to be."] = "Oui, enfin... tout s'est passé si vite ! Dans un dernier souffle, la courageuse Golvyni s'est jetée dans la mêlée pour me sauver. Je... je ne méritais pas un tel courage... mais je m'en montrerai digne.",
    ["How long have you and Golvyni worked together?"] = "Depuis combien de temps Golvyni et vous collaborez-vous ?",
    ["Oh, where has this day gone? Speaking of my business, I really must be getting back to it now.\n\nFriend, Golvyni is at peace, you have your gold. Let it go. I have bear-lizards to skin and an ailing mother to visit."] = "Oh, mais vous avez vu l'heure ? En parlant d'affaires, il faut que je me remette au travail.\n\nMon <<player{ami/amie}>>, Golvyni est en paix, vous avez votre or. Restons-en là. J'ai des lézards-ours à dépecer, et une mère souffrante à aller voir.",
    ["I was inspired enough by Dullard and his crew to write an epic poem based on their adventures.\n\nWhile doing a reading just now, he felt the need to interrupt and take issues with my creative liberties regarding his selection of bedfellows."] = "Le Demeuré et son équipage m'ont inspiré un poème épique qui raconte leurs aventures.\n\nAlors que je faisais une lecture, il a ressenti le besoin de m'interrompre, et de commenter mes libertés créatives sur ses partenaires de couche.",
    ["The words of the dead? Really? You're going to believe scribbles in a journal instead of a hunter with an impeccable reputation? No, I fail to see how I deceived you. I only asked for help.\n\nBut you just wanted to be difficult …."] = "Vraiment, vous voulez faire parler les morts ? Vous allez croire les gribouillis de ce journal plutôt qu'un chasseur à la réputation immaculée ? Non, je ne vois pas en quoi je vous ai menti. Je vous ai simplement demandé votre aide.\n\nMais vous avez voulu faire votre mauvaise tête...",
    ["Gather Bait"] = "Prenez l'appât",
    ["Are you afraid? Don't be. The cowardly are better to us dead than alive, and I will not hesitate to add your life to our power. \n\nSteel yourself. Soon, we rid this fortress of Naemon's presence!"] = "Vous avez peur ? Vous ne devriez pas. Les lâches sont plus utiles morts que vifs, et je n'hésiterai pas à ajouter votre vie à notre pouvoir.\n\nPréparez-vous. Bientôt, nous débarrasserons cette forteresse de la présence de Næmon !",
    ["Just one, but it requires a favor. I know, you've done plenty already. But could you find a way in, fix the platforms, maybe dispel a few wards? Meridia does love her magic traps! Then we can head inside.\n\nEasy stuff. You got this, right?"] = "Une seule, mais ça m'oblige à vous demander un service. Je sais, vous en avez déjà fait beaucoup. Mais vous pourriez trouver un moyen d'entrer, réparer les plateformes, et peut-être désactiver quelques protections ? Méridia aime les pièges magiques ! Ensuite, nous pourrons entrer.\n\nC'est facile. Vous pouvez le faire, hein ?",
    ["You were there? Perhaps you met Er-Jaseen. Crown and beard of black spines. Swishing tail. A kindness in his eyes."] = "Vous y étiez ? Vous avez peut-être rencontré Er-Jaseen. Une couronne et une barbe de piques noires. Une queue cinglante. Mais un regard bienveillant.",
    ["Er-Jaseen. He helped Argie escape the Wailing Prison. I meant for him to escape with me, but he stayed behind to help the others. \n\nThere were so many others. I don't know if he escaped. I should never have let him stay behind."] = "Er-Jaseen. Il m'a aidée à quitter la Prison des lamentations. Je voulais qu'il s'échappe avec moi, mais il est resté en arrière pour aider les autres.\n\nIl y en avait tellement. Je ne sais pas s'il s'est échappé. Je n'aurais jamais dû le laisser.",
    ["Walked right into that one, didn't I?\n\nIf only Salvus was here. You'd have him in stitches. No mirrors on the Spriggan. Heh."] = "J'ai tendu la perche, là.\n\nSi seulement Salvus était là. Il se tordrait de rire. Pas de miroirs sur le Spriggan. Ha.",
    ["Find the Oblivion Boulder"] = "Trouvez le rocher d'Oblivion",
    ["Without a single one of our crew seeing you? Hmm. Maybe you are the right sort to take out that observer.\n\nTry not to disappoint me, all right?"] = "Sans qu'aucun membre de notre équipage ne vous voie ? Hmm. Vous êtes peut-être la bonne personne pour nous débarrasser de cet observateur.\n\nEssayez de ne pas me décevoir, d'accord ?",
    ["Remember Camlorn. Your dad. Alinon. The people there."] = "Souvenez-vous de Camlorn. Votre père. Alinon. Tous vos amis.",
    ["Remember Shornhelm. Sneaking into Northpoint. Your … antics."] = "Souvenez-vous de Taillemont. Notre entrée dans Pointe-Nord. Vos... facéties.",
    ["Remember Coldharbour. How we fought alongside King Dynar. How we stopped Molag Bal."] = "Souvenez-vous de Havreglace. Notre combat avec le roi Dynar. Comment nous avons arrêté Molag Bal.",
    ["I have gone to great lengths to define my authority and the boundaries of the prince's. No one will confuse them again.\n\nIf there are any issues, come to me or one of my aides. We will be more than pleased to clarify who is in charge here."] = "J'ai pris soin de définir mon autorité et les limites de celle du prince. Personne ne les confondra.\n\nS'il y a le moindre problème, venez me voir. Nous clarifierons avec joie la chaîne de commandement.",
    ["I am, of course, limited by the bargains I strike with prevailing Princes, but yes. I am a Daedra with many forms. But I do not use this gift to seek power.\n\nOnce I have experienced all Oblivion has to offer, I will finally know who I am."] = "Je suis bien sûr limité par les pactes que je noue avec les Princes locaux. Mais oui, je suis un Daedra aux formes multiples. Mais je ne m'en sers pas pour gagner en pouvoir.\n\nUne fois que j'aurai vécu toutes les expériences qu'Oblivion propose, je saurai enfin qui je suis.",
    ["I can spare a few moments before I resume my preparations to return to the mainland. You've more than earned the right to ask questions, champion."] = "Je peux vous consacrer quelques instants avant de reprendre les préparatifs de mon retour sur le continent. Vous avez largement mérité de poser quelques questions, <<player{champion/championne}>>.",
    ["Why would Molag Bal make vampires fight each other?"] = "Pourquoi Molag Bal forcerait-il des vampires à se battre entre eux ?",
    ["Looking for inspiration! I heard all about the goings-on here and I tried to get here as fast as I could.\n\nSeems like most of the good stuff happened without me here to witness. I'm trying to get what information I can so the trip isn't a total loss."] = "Je cherche l'inspiration ! On m'a parlé des événements, et je suis venu au plus vite.\n\nOn dirait que le meilleur a eu lieu en mon absence. Alors j'essaie de rassembler des informations pour que ce voyage ne soit pas entièrement du gâchis.",
    ["As vampires age, they gain strength. Physically and magically. And coming here breaks your morality after a while. The kind don't grow old.\n\nElder prisoners force the young to protect them. At threat of exsanguination."] = "En vieillissant, les vampires gagnent en force. Physique et magique. Et lorsqu'on vit ici, on finit par perdre tout sens moral. Les tendres ne font pas de vieux os.\n\nLes prisonniers anciens forcent les jeunes à les protéger. Sous peine d'exsanguination.",
    ["As good as I can be after whatever that was in the temple. Did Vanus fill you in? I tried to avoid him, but he's surprisingly limber for a centuries old mage.\n\nBut we're not here to talk about Vanus. Unless you … want to talk about Vanus?"] = "Autant que faire se peut, après ce qui s'est passé dans le temple. Vanus vous a tout raconté ? J'ai essayé de l'éviter, mais il a le pas très vif, pour un mage pluricentenaire.\n\nMais nous ne sommes pas là pour parler de Vanus. Sauf si... vous vouliez parler de Vanus ?",
    ["Observe Sirilonwe's Magic"] = "Observez la magie de Sirilonwë",
    ["Search the Broken Walkway"] = "Fouillez la passerelle brisée",
    ["Perform a Dance in the Mud"] = "Dansez dans la boue",
    ["Use any Musical Emote"] = "Utilisez n'importe quel emote musical",
    ["Player Logged Out"] = "Le joueur s'est déconnecté",
    ["Player Died"] = "Le joueur est mort",
    ["Notes written by Vanus Galerion to Gabrielle and smuggled out of his prison by Baar-Jasa."] = "Des notes que Vanus Galérion a écrites dans sa cellule pour Gabrielle, et qu'il avait confiées à Baar-Jasa.",
    ["Not precisely, but they know to head to the portal gates in emergencies. However, they need a keystone to activate them and return to Sunport.\n\nTake my keystone. Activate the portals and save my apprentices. I promise to reward you for your efforts."] = "Pas exactement, mais ils savent qu'ils doivent se rassembler aux portails en cas d'urgence. Cela dit, il leur faut une pierre-clef pour les activer et rentrer à Hélioport.\n\nPrenez ma pierre-clef. Activez les portails et sauvez mes apprentis. Je vous promets de vous récompenser.",
    ["Captain One-Eye. She'll know what to do. Help us, and I'll make sure she cuts you in for a share of our plunder.\n\nThe ships came down by those cliffs to the north. I think, if the captain made it, that is where she'll rally the crew."] = "Le capitaine Un-Œil. Elle saura quoi faire. Aidez-nous, et je m'assurerai qu'elle vous donnera une part du butin.\n\nLes navires sont arrivés près de ces falaises, au nord. Je crois. Si le capitaine s'en est tiré, c'est là qu'elle ralliera l'équipage.",
    ["You can't find anyone to help you out?"] = "Vous ne trouvez personne qui puisse vous aider ?",
    ["I'll help. What exactly do you need me to do?"] = "Je vais vous aider. Que dois-je faire, exactement ?",
    ["You made all this food for someone else?"] = "Vous avez préparé tout cela pour quelqu'un d'autre ?",
    ["A lot of someones, actually. It's an offering for elders in our community. A chance to pay them back for years of wisdom this New Life, but I'm struggling to find anyone to help me with the final preparations."] = "Pour plusieurs autres personnes, en fait. C'est une offrande pour les aînés de notre communauté. Une occasion de les remercier pour leurs années de sagesse à l'occasion de cette Nouvelle vie. Mais je ne trouve personne pour m'aider avec les derniers préparatifs.",
    ["Everyone's busy with something, from the Three Banners War to a knotted ball of their own problems. And some simply don't care.\n\nSince you seem even the least bit interested, would you be willing to help me? For New Life, and for pay, of course."] = "Tout le monde est occupé, de la Guerre des Trois étendards à une vraie pelote de problèmes personnels. Et d'autres s'en fichent complètement.\n\nPuisque vous avez l'air de vous intéresser un peu à l'affaire, vous pourriez m'aider ? Pour la Nouvelle vie, et pour être <<player{payé/payée}>>, bien sûr.",
    ["A little help for New Life would be appreciated …."] = "Un peu d'aide pour la Nouvelle vie, ce ne serait pas de refus...",
    ["A coin swiped from the hoard of Rawl'kha's Dragon as part of the New Life Festival."] = "Une pièce volée dans le trésor du dragon de Rawl'kha dans le cadre du Festival de la Nouvelle vie.",
    ["Dragon's Coin"] = "pièce du dragon^fd",
    ["Tricky in what way?"] = "C'est-à-dire ?",
    ["All right. Where can I find the Dragon?"] = "D'accord. Où est le dragon ?",
    ["Rawl'kha's Dragon?"] = "Le dragon de Rawl'kha ?",
    ["Tibarr apologizes. This one did not mean to alarm. We are in no danger. It is our New Life tradition to steal the Dragon's treasure and distribute it to the needy. Tibarr always organizes it!\n\nHowever, this season's challenge has been … tricky."] = "Pardonnez-moi. Je ne voulais pas vous alarmer. Nous ne courons aucun danger. Notre tradition de la Nouvelle vie veut que nous volions le trésor d'un dragon pour le distribuer aux nécessiteux. C'est toujours moi qui l'organise !\n\nMais le défi de cette saison est... délicat.",
    ["Now, that would spoil the fun! This New Life tradition seeks to help us sharpen both our minds and our claws. Will you try to abscond with the Dragon's hoard?\n\nTibarr promises a portion of the gold will be yours to keep!"] = "Allons, ça gâcherait tout le plaisir ! Cette tradition de la Nouvelle vie nous aide à affûter notre esprit et nos griffes. Essaierez-vous de filer avec le trésor du dragon ?\n\nJe vous promets que vous pourrez garder une portion de l'or.",
    ["Who will face Rawl'kha's Dragon for New Life?"] = "Qui osera affronter le dragon de Rawl'kha pour la Nouvelle vie ?",
    ["Fresh mud collected for Dailonda's Mudman."] = "De la boue fraîche ramassée pour l'homme de boue de Dailonda.",
    ["Mudman Mud"] = "boue à homme de boue^f",
    ["What's making it so difficult?"] = "Qu'est-ce qui fait que ce soit si difficile ?",
    ["All right. Where can I find the Dakoi?"] = "D'accord. Où puis-je trouver le dakoï ?",
    ["Who's Dakoi?"] = "Qui est le dakoï ?",
    ["Not a who. A what! Dakoi is a very special, sly … fish. Every New Life season, it greets our waters. It's said good fortune and growth comes to those who feast on this particular fish.\n\nBut, lately, it's proving difficult to catch."] = "Pas qui, mais quoi ? Le dakoï est un... poisson spécial, très rusé. À chaque saison de la Nouvelle vie, il s'installe dans nos eaux. On dit que la fortune et la croissance sourient à ceux qui mangent sa chair.\n\nMais il est devenu très difficile à attraper.",
    ["The fish has more tricks than a New Life Festival performer! I promised to reel it in for tonight's feast, but the Dakoi …. I refuse to be embarrassed any further!\n\nHunt the Dakoi for me, and I guarantee you'll get more than just good fortune."] = "Ce poisson est plus rusé qu'un saltimbanque de la Nouvelle vie ! J'ai promis d'en pêcher un pour le festival de ce soir, mais le dakoï... Je refuse de me laisser humilier !\n\nTraquez-moi ce dakoï, et je vous garantis que votre fortune sera faite.",
    ["That clever little Dakoi can't elude me forever."] = "Ce petit malin de dakoï ne m'échappera pas éternellement.",
    ["Forged by Orsimer Orcs to break boulders for Betnikh's Boon in the New Life Festival."] = "Forgé par les Orques orsimers pour briser des rochers pour le bienfait de Betnikh pendant le Festival de la Nouvelle vie.",
    ["Where are your kin?"] = "Où est votre famille ?",
    ["All right. What kind of mud do you need?"] = "D'accord. De quel genre de boue avez-vous besoin ?",
    ["What kind of blessing?"] = "Quel genre de bénédiction ?",
    ["Orsimer Hammer"] = "marteau d'Orsimer^md",
    ["One only available during New Life. The Mudman is an effigy my kin and I construct to bless the new year with fertile growth across all of Tamriel.\n\nAnd … now I must do it without them."] = "Elle n'est disponible que pendant la Nouvelle vie. L'homme de boue est une effigie que ma famille et moi assemblons pour bénir la Nouvelle vie et garantir de bonnes récoltes dans tout Tamriel.\n\nEt... maintenant, je dois m'en charger seule.",
    ["Gone to spread their roots beyond Grahtwood. My home is here with my followers, but with our numbers reduced, we struggle to complete the Mudman.\n\nI believe your path through the Green has led you here. Help us gather mud and you'll be rewarded."] = "Partie étendre ses racines au-delà du bois de Graht. Mon foyer est encore ici, avec mes adeptes, mais nous sommes moins nombreux, et nous peinons à terminer l'homme de boue.\n\nJe pense que votre chemin dans le Vert vous a <<player{mené/menée}>> jusqu'à nous. Aidez-nous à rassembler de la boue, et vous serez <<player{récompensé/récompensée}>>.",
    ["Let our prayers bring the Mudman to life!"] = "Que nos prières donnent vie à l'homme de boue !",
    ["A sweet and succulent honeycomb. Surely this will lighten the mood of the hermit's bear, Garth."] = "Du miel, riche et succulent. Cela devrait rendre le sourire à Garth, l'ours de l'ermite.",
    ["You want me to smash a boulder?"] = "Vous voulez que je casse un rocher ?",
    ["I accept your challenge. What kind of boulder do you have in mind?"] = "J'accepte votre défi. À quel genre de rocher pensez-vous ?",
    ["What sort of competition?"] = "Quel genre de compétition ?",
    ["Just the best New Life has to offer! We haul in big boulders and smash them. Whoever breaks a boulder into the smallest bits with one strike claims a boon of good health until the next New Life.\n\nAnd with bragging rights, of course."] = "La meilleure activité de toute la Nouvelle vie ! On apporte des gros rochers, et on les casse. Celui qui obtient les plus petits morceaux en un seul coup gagne une récompense de bonne santé jusqu'à la prochaine Nouvelle vie.\n\nEt il peut se vanter, bien sûr.",
    ["Not just any boulder! Let's make it interesting and find one that's truly worthy of Betnikh's Boon! Something none of these losers could ever hope to chip or crack. I'll even throw in something extra for the winner. \n\nSo, friend, what do you say?"] = "Pas n'importe quel rocher ! Essayons de corser les choses et d'en trouver un qui serait digne du bienfait de Betnikh ! Quelque chose que ces pauvres larves n'auraient aucune chance d'ébrécher. J'ajouterai même une récompense supplémentaire pour le gagnant.\n\nAlors, mon <<player{ami/amie}>>, qu'en dites-vous ?",
    ["Can no one provide a proper challenge this New Life?"] = "Personne ne peut-il me donner un vrai défi pour cette Nouvelle vie ?",
    ["Why is Garth in a bad mood?"] = "Pourquoi Garth est-il de mauvaise humeur ?",
    ["All right. Where can I find some honeycomb?"] = "Très bien. Mais où puis-je trouver du miel ?",
    ["Garth wants to eat Tamriel?"] = "Garth veut dévorer Tamriel ?",
    ["Eat, destroy, same difference. The Skaals in the village don't believe it, but Garth has a piece of the All-Maker in him. And it's his jolly mood during New Life that determines Tamriel's fate for the coming year!\n\nRight now, it's not looking good."] = "Dévorer, détruire, cela revient au même. Les Skaals du village ne me croient pas, mais Garth a un aspect de l'Omnifaiseur en lui. Et c'est sa bonhomie qui va décider du sort de Tamriel pour l'année à venir !\n\nEt pour le moment... il fait grise mine.",
    ["Ask the fool in his belly the next time you meet him. At least he was calm while I juggled and … wait.\n\nHoneycomb! That will brighten Garth's mood! Bring him some while I keep juggling and we may just save Tamriel and New Life yet!"] = "Demandez cela à l'idiot dans son estomac, la prochaine fois que vous le verrez. Au moins, il était calme tant que je jonglais, et... attendez.\n\nDu miel ! Voilà qui égaiera Garth ! Apportez-moi du miel pendant que je jongle, et nous avons une chance de sauver Tamriel et la Nouvelle vie !",
    ["What's wrong, Garth? My juggling used to soothe you."] = "Ça ne va pas, Garth ? Ça t'amuse quand je jongle, d'habitude.",
    ["Despite its seemingly ancient make, this water skin shows no signs of wear and tear."] = "Malgré sa facture ancienne, cette outre ne montre aucun signe d'usure.",
    ["What is Anseilak, and how do I give them that?"] = "Qu'est-ce que l'Anseilak, et comment la leur donner ?",
    ["All right. I'll help you perform Anseilak for the Yokudan mages."] = "Très bien. Je vais vous aider à donner l'Anseilak aux mages yokudans.",
    ["No. What're you on pilgrimage for?"] = "Non. En quoi consiste votre pèlerinage ?",
    ["Withered Water Skin"] = "outre asséchée^f",
    ["If only I could survive the journey. Every New Life, we give Anseilak to the fallen Yokudans so that their spirits may rest peacefully. However, Yokudan mages are ignored for their involvement in magic.\n\nTraveler. Will you give them Anseilak?"] = "Si seulement je pouvais survivre à ce voyage. À chaque Nouvelle vie, nous donnons l'Anseilak aux Yokudans défunts, pour que leur esprit repose en paix. Mais les mages yokudans sont ignorés, parce qu'ils pratiquaient la magie.\n\n<<player{Voyageur/Voyageuse}>>. Acceptez-vous de leur donner l'Anseilak ?",
    ["Forgive me. It is a ritual where we gather seawater that once touched Yokuda's lands. We then perform it for the fallen mages resting at Motalion Necropolis, bringing them peace.\n\nKnow your efforts will be repaid in full."] = "Pardonnez-moi. C'est un rituel au cours duquel nous collectons de l'eau de mer qui touchait autrefois les terres yokudanes. Nous menons ensuite ce rituel pour les mages défunts qui reposent dans la nécropole de Motalion afin de leur garantir la paix.\n\nSachez que vos efforts seront récompensés.",
    ["I must bring peace to the rest of the Yokudans."] = "Je dois apporter la paix au reste des Yokudans.",
    ["Water that once touched the ancient land of Yokuda, now sunken deep beneath the sea."] = "L'eau qui baignait autrefois l'antique territoire de Yokuda, englouti sous les flots.",
    ["Fresh Seawater"] = "eau de mer fraîche^fs",
    ["You prepared a hearty, rich baked potato for Nenilon. Deliver it to him near the banks of Toothmaul Gully as an offering for New Life."] = "Vous avez préparé une pomme de terre au four très riche pour Nenilon. Apportez-la-lui près des rives de la ravine du Chicot, en guise d'offrande pour la Nouvelle vie.",
    ["I learned that Lanullin is leading an effort to give back to esteemed High Elf elders in her community. However, it seems they're shorthanded. I agreed to help her however I can."] = "J'ai appris que Lanullin avait entrepris de remercier les aînés les plus estimables de sa communauté. Mais elle semble avoir besoin d'aide. J'ai accepté d'apporter ma contribution.",
    ["Giving back? How?"] = "Rendre à la communauté ? Comment ?",
    ["All right. I'll help Lanullin in Auridon."] = "Très bien. Je vais aider Lanullin à Auridia.",
    ["I'm interested. Tell me more."] = "Ça m'intéresse. Dites-m'en davantage.",
    ["Nenilon's Baked Potato Offering"] = "pomme de terre au four de Nenilon^fd",
    ["Here's a New Life festivity that strikes a chord in me. Lanullin leads an earnest effort to give back to High Elf elders this season, especially those who shared their wisdom with her community."] = "Voici une festivité de la Nouvelle vie qui me touche. Lanullin s'efforce de témoigner son respect aux anciens Hauts-Elfes en cette saison, surtout ceux qui ont partagé leur sagesse avec sa communauté.",
    ["By rattling pots and pans and cooking up something delicious! A shame, though. I hear she doesn't have enough help to make offerings for all the elders she hopes to provide for.\n\nCould you lend them a hand in Auridon, friend?"] = "En agitant les poêles et les casseroles pour préparer quelque chose de délicieux ! Mais il paraît qu'elle n'a pas assez de bras pour l'aider à préparer tous les plats qu'elle comptait leur apporter.\n\nVous pourriez aller l'aider sur Auridia, mon <<player{ami/amie}>> ?",
    ["Help support Auridon's elders for New Life!"] = "Aidez les anciens d'Auridia pour la Nouvelle vie !",
    ["You prepared a sweet and tempting banana surprise for Geraldrim. Deliver it to him near the Ezduiin's Ruins as an offering for New Life."] = "Vous avez préparé une banane surprise délicieuse et alléchante pour Geraldrim. Apportez-la-lui près des ruines d'Ezduiin, en guise d'offrande pour la Nouvelle vie.",
    ["A wealthy Khajiit seems to be hosting a game for New Life that involves hoards of gold and a grand opponent guarding it. To learn more, I need to speak to Tibarr, the organizer for this festivity."] = "Un riche Khajiit semble organiser un jeu pour la Nouvelle vie, où un adversaire imposant protège des tas d'or. Pour en savoir davantage, je dois parler à Tibarr, l'organisateur de ces festivités.",
    ["Tell me about this guardian."] = "Parlez-moi du gardien.",
    ["All right. I'll speak to Tibarr in Rawl'kha."] = "Très bien. Je vais aller parler à Tibarr à Rawl'kha.",
    ["Geraldrim's Banana Surprise Offering"] = "banane surprise de Geraldrim^fd",
    ["I hesitate to mention due to the danger, but you seem the daring sort. A wealthy Khajiit in Rawl'kha has put a hoard of gold on the line—if you can overcome its guardian."] = "J'hésite à en parler, au vu du danger, mais vous avez l'air téméraire. Un riche Khajiit de Rawl'kha a mis une petite fortune en jeu... si vous parvenez à échapper à son gardien.",
    ["New Life is about surprises, too, my friend! I'll let Tibarr be the one to reveal his grand scheme to you.\n\nBut a word of caution—watch your step when you face the guardian!"] = "La Nouvelle vie est aussi une histoire de surprises, mon <<player{ami/amie}>> ! Je laisserai Tibarr vous expliquer son projet.\n\nMais je vous préviens... attention où vous mettez les pieds face au gardien !",
    ["Here's a New Life festivity for those who love a challenge!"] = "Voilà une festivité de la Nouvelle vie pour ceux qui aiment les défis !",
    ["You prepared a warm, nourishing carrot soup for Teliwe. Deliver it to her at the College of Aldmeri as an offering for New Life."] = "Vous avez préparé une soupe de carottes chaude et nourrissante pour Teliwë. Apportez-la-lui à l'École de maintien aldmeri, en guise d'offrande pour la Nouvelle vie.",
    ["Anicus mentioned an angler called Yesei trying to catch a fabled Dakoi fish for New Life. He thinks he needs help, and that I should speak to him."] = "Anicus a parlé d'un pêcheur appelé Yesei qui tente d'attraper un poisson de légende, le dakoï, pour la Nouvelle vie. Il pense qu'il a besoin d'aide et que je devrais lui parler.",
    ["Interesting. Tell me more."] = "Intéressant. Dites-m'en davantage.",
    ["All right. I'll find Yesei in Stormhold."] = "Très bien. Je vais aller voir Yesei à Havre-tempête.",
    ["Teliwe's Carrot Soup Offering"] = "soupe de carottes de Teliwë^fd",
    ["Let me tell you about the murky waters of Stormhold. Nearly fell in when a poor angler rushed past me in pursuit of the fabled Dakoi fish.\n\nIt's a strange way to celebrate New Life, but that's what makes it special!"] = "Laissez-moi vous parler des eaux troubles de Havre-tempête. J'ai failli y tomber quand un pêcheur pressé m'a bousculé pour suivre le fabuleux dakoï.\n\nC'est une façon étrange de fêter la Nouvelle vie, mais c'est tout l'intérêt !",
    ["The Dakoi only appears during the New Life season. Poor Yesei has been chasing it all over Stormhold. Whoever catches it gets a year of good luck, and Yesei could really use some.\n\nIf you don't mind getting a little wet, go help him out!"] = "Le dakoï n'apparaît que pendant la Nouvelle vie. Le pauvre Yesei le traque dans tout Havre-tempête. Celui qui le pêchera aura de la chance toute l'année, et Yesei en a cruellement besoin.\n\nSi ça ne vous ennuie pas de vous mouiller, allez donc l'aider !",
    ["Will you be the one to hook Stormhold's fabled Dakoi this season?"] = "Pêcherez-vous le fabuleux dakoï de Havre-tempête pour les fêtes ?",
    ["Prepare carrot soup and deliver it to Teliwe at the College of Aldmeri as an offering for New Life."] = "Préparez de la soupe de carottes et livrez-la à Teliwë à l'École de maintien aldmeri, en guise d'offrande pour la Nouvelle vie.",
    ["In Elden Root, Dailonda and her followers are constructing a Mudman effigy to bless Tamriel, but they need a hand. I agreed to help her however I can."] = "À Faneracine, Dailonda et ses adeptes construisent une effigie de l'homme de boue pour bénir Tamriel, mais ils ont besoin d'aide. J'ai accepté de l'aider de mon mieux.",
    ["Mudman effigy? She's sculpting with mud?"] = "Une effigie de l'homme de boue ? Elle sculpte de la boue ?",
    ["I'll head to Elden Root and help Dailonda."] = "Je vais aller à Faneracine pour aider Dailonda.",
    ["This one's a bit messy. Dailonda's kin usually help her with the sculpting for New Life, but they all recently departed Elden Root's branches for newer trees.\n\nNow, it's only her, a few of her followers, and their Mudman effigy."] = "Celle-ci est un peu salissante. La famille de Dailonda l'aide généralement à sculpter pour la Nouvelle vie, mais ils ont récemment quitté les branches de Faneracine pour d'autres arbres.\n\nElle est seule avec quelques adeptes et leur effigie de l'homme de boue. Qui est couché, il me semble.",
    ["Like I said, messy. When completed, the Mudman bestows its blessing upon Tamriel. But poor Dailonda also believes that bad luck follows if the sculpture isn't finished.\n\nSo, are you up for frolicking in the mud and lending a hand?"] = "Comme je vous ai dit, c'est salissant. Une fois terminé, l'homme de boue bénit Tamriel. Mais la pauvre Dailonda croit que si la sculpture reste inachevée, cela nous portera malheur.\n\nAlors, vous voulez bien jouer dans la boue pour l'aider ?",
    ["Who doesn't mind a little dirt for a New Life blessing?"] = "Tout le monde aime se salir pour la Nouvelle vie !",
    ["Prepare a baked potato and deliver it to Nenilon near the banks of Toothmaul Gully as an offering for New Life."] = "Préparez une pomme de terre au four et livrez-la à Nenilon près des rives de la ravine du Chicot, en guise d'offrande pour la Nouvelle vie.",
    ["I learned that a group of Orcs in Betnikh celebrate New Life by breaking boulders for a special boon. To participate, I need to speak to Mahagog, their leader."] = "J'ai appris qu'un groupe d'Orques de Betnikh fêtent la Nouvelle vie en brisant des rochers pour un bienfait spécial. Pour participer, je dois parler à leur chef, Mahagog.",
    ["What's Betnikh's Boon?"] = "Qu'est-ce que c'est, le bienfait de Betnikh ?",
    ["All right. I'll talk to Mahagog at Stonetooth Fortress."] = "Très bien. Je vais aller parler à Mahagog, à la forteresse de Pierrecroc.",
    ["Orcs over in Betnikh compete for Betnikh's Boon in a contest of strength every New Life. The competition involves physical strength, keen reflexes, and huge boulders!"] = "Les Orques de Betnikh s'affrontent pour le bienfait de Betnikh dans un concours de force à chaque Nouvelle vie. La compétition est une histoire de force physique, de réflexes et de rochers !",
    ["A favor or benefit of some kind. You'd have to ask Mahagog. He's leading the contest. You can find him at Stonetooth Fortress in Betnikh.\n\nFair warning—he loves competition and hates to lose."] = "Une sorte de faveur. Il faudrait demander à Mahagog. C'est lui qui organise le concours. Vous le trouverez à la forteresse de Pierrecroc, à Betnikh.\n\nJe vous préviens, c'est un compétiteur, il a horreur de perdre.",
    ["If you've got muscles, I've got a New Life festivity for you!"] = "Si vous avez des muscles, j'ai une festivité de la Nouvelle vie pour vous !",
    ["Prepare a banana surprise and deliver it to Geraldrim near the Ezduiin's Ruins as an offering for New Life."] = "Préparez une banane surprise et livrez-la à Geraldrim près des ruines d'Ezduiin, en guise d'offrande pour la Nouvelle vie.",
    ["A lone traveler seems to be asking for help making a pilgrimage. Supposedly, it can help bring peace to the fallen Yokudans during New Life. I agreed to help however I can."] = "Quelqu'un a besoin d'aide pour mener un pèlerinage. Il permettrait d'apporter le repos aux Yokudans défunts pendant la Nouvelle vie. J'ai accepté de l'aider.",
    ["Any reason why nobody wants to help them?"] = "Vous savez pourquoi personne ne veut l'aider ?",
    ["All right. I'll find them in Sentinel."] = "D'accord, je vais à Sentinelle.",
    ["This one I haven't been able to check personally. Whispers carried by Sentinel's winds tell of a lone traveler seeking help from passersby for New Life. Something about a pilgrimage to bring fallen Yokudans peace.\n\nAlas, the pleas fall on deaf ears."] = "Je n'ai pas pu aller voir personnellement. Le vent de Sentinelle parle d'un voyageur solitaire qui demande de l'aide aux passants pour la Nouvelle vie. Une histoire de pèlerinage pour apporter la paix à des Yokudans défunts.\n\nMais personne ne lui répond.",
    ["Who can say? I hear Redguard have peculiar notions regarding the dead, so perhaps that's part of it.\n\nIf you can deal with hot sand and biting winds, seek them out in Sentinel. It would be a shame if their approach to New Life didn't succeed."] = "Qui sait ? Il paraît que les Rougegardes ont des opinions très particulières sur les morts, alors c'est peut-être lié.\n\nSi vous supportez le sable chaud et le vent mordant, allez le voir à Sentinelle. Ce serait dommage que sa tradition de la Nouvelle vie reste inachevée.",
    ["New Life and long dead in Sentinel! Ask me for details!"] = "La Nouvelle vie pour les morts de Sentinelle ! Demandez-moi des détails !",
    ["Many Nords seem to describe a hermit claiming that his pet bear's mood is important this New Life. I should speak to him to learn more about what he needs."] = "De nombreux Nordiques ont décrit un ermite qui prétend que l'humeur de son ours serait importante pour la Nouvelle vie. Je devrais lui parler pour savoir de quoi il a besoin.",
    ["His bear?"] = "Son ours ?",
    ["All right. I'll head to the Rift and talk to the hermit."] = "Très bien. Je vais aller à la Faille parler à cet ermite.",
    ["Here's a bizarre one I haven't had a chance to check on yet. A crazed hermit in the Rift proclaims this will be the last New Life. That the end of days are upon us. Heh, what else is new?\n\nBut here's the twist—his bear is the problem."] = "Voici une histoire bizarre que je n'ai pas encore eu le temps de vérifier. Un ermite fou de la Faille affirme que ce sera notre dernière Nouvelle vie. Que la fin du monde est proche. Ce qui est généralement vrai, vous me direz.\n\nMais là où c'est intéressant, c'est que le problème vient de son ours.",
    ["Pet bear, yes. Seems like the bear's mood determines the fate of each New Life, and right now the bear is miserable. The hermit needs help cheering him up.\n\nThe bear's also … quite large. Hard to miss. Find them by a lake near Skald's Retreat."] = "Un ours apprivoisé, oui. Apparemment, l'humeur de l'ours détermine l'issue de chaque Nouvelle vie, et pour le moment, l'ours n'a pas la forme. L'ermite a besoin d'aide pour lui remonter le moral.\n\nEt l'ours est... très gros. Difficile de le rater. Vous les trouverez près d'un lac, du côté de la retraite du Scalde.",
    ["Hermit claims this may be Tamriel's last New Life! Talk to me to learn more!"] = "Un ermite affirme que ce sera la dernière Nouvelle vie de Tamriel ! Venez me parler pour en savoir plus.",
    ["An empty bottle of bloodwine that still has a strong scent to it."] = "Une bouteille de vin de sang vide. L'odeur est encore très forte.",
    ["I met Jahesi once again out in Sentinel. It seems she'd like to continue performing Anseilak for the fallen Yokudan mages until New Life's end. I agreed to travel with her and help with the ritual."] = "J'ai retrouvé Jahesi à Sentinelle. On dirait qu'elle aimerait continuer son Anseilak pour les mages yokudans défunts pendant la Nouvelle vie. J'ai accepté de voyager avec elle et de l'aider avec le rituel.",
    ["And you're going to do this every day?"] = "Et vous allez faire cela tous les jours ?",
    ["All right. Let's perform Anseilak."] = "Très bien. Allons donner l'Anseilak.",
    ["Do you need help with something?"] = "Vous avez besoin d'aide ?",
    ["Bottle of Bloodwine"] = "bouteille de vin de sang^f",
    ["I need to perform Anseilak for the other Yokudan mages, but my blessing alone won't be enough to make up for the centuries they've been shunned. And most Redguard scowl when I mention them."] = "Je dois donner l'Anseilak aux autres mages yokudans, mais ma bénédiction ne suffira pas à compenser les siècles durant lesquels on les a ignorés. Et la plupart des Rougegardes grimacent lorsque je les évoque.",
    ["Until New Life's end. You certainly don't have to trudge through the sand with me every day. But having another blessing would help the mages. And me.\n\nRest assured I'll reward you for your time."] = "Jusqu'à la fin de la Nouvelle vie. Rien ne vous oblige à traverser les sables tous les jours. Mais une bénédiction de plus serait bénéfique pour les mages. Et pour moi.\n\nBien sûr, je vous dédommagerai pour le temps que vous nous consacrerez.",
    ["Alik'r's winds have reunited us once more, traveler."] = "Les vents d'Alik'r nous réunissent à nouveau, <<player{voyageur/voyageuse}>>.",
    ["A wet, earthy clump of mud. Caught and reeled from Shadowfen's fishing holes."] = "Une poignée de boue humide et épaisse. Prise et remontée d'un trou de pêche de Fangeombre.",
    ["Clump of Mud"] = "poignée de boue^f",
    ["Shriveled fish scales. Probably the leftovers of a predator's meal."] = "Des écailles de poisson desséchées. Sans doute les restes du repas d'un prédateur.",
    ["Bundle of Fish Scales"] = "paquet d'écailles de poissons^m",
    ["I don't know what the Worm Cult wants with the Staff of Magnus or Prince Naemon, but it sounds disastrous. Queen Ayrenn, the Dominion, everything is in jeopardy.\n \nI have the beginnings of a plan, but I can't move fast enough with this injury."] = "Je ne sais pas ce que le Culte du Ver veut faire avec le bâton de Magnus ou le prince Næmon, mais ça ne peut être que désastreux. La reine Ayrenn, le Domaine et tout le reste sont en danger.\n\nJ'ai l'esquisse d'un plan, mais je ne suis plus assez rapide, avec cette blessure.",
    ["A Trick to the Doors"] = "L'astuce des portes^M",
    ["What does it hurt to spin some yarn about me dying like a hero? I just want her to remember me with fondness, that's all.\n\nI'm sure she'll pay you for your delivering the news. She has a good heart. Please. Above all else, she needs to know."] = "Ça ne fera de mal à personne de broder un peu pour donner à ma mort un tour héroïque. J'aimerais qu'elle se souvienne de moi avec tendresse, c'est tout.\n\nJe suis sûr qu'elle vous paiera si vous lui apportez la nouvelle. Elle a bon cœur. S'il vous plaît. Avant tout, il faut qu'on la prévienne.",
    ["A carelessly dropped note written by Terinvel. Sirilonwe wants to see it."] = "Une note que Terinvel a laissée tomber par inadvertance. Sirilonwë veut la voir.",
    ["Glenumbra"] = "Glénumbrie^fd",
}